import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { startFrame: number; endFrame?: number; word?: string; index?: number; wordIndex?: number };
type ShotProps = { wordCues?: WordCue[] };
type Capability = { key: string; label: string; at: number; side: -1 | 1; lower: boolean; x: number; y: number; plateWidth: number; path: string; connector: string; dx: number; dy: number };

const C = { bg: '#10191F', white: '#F3F1EB', raised: '#FFFFFF', ink: '#17262C', slate: '#65757C', teal: '#147D87', coral: '#E96B53', brass: '#BA934C' };
const clamp = { extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const };
const ease = Easing.bezier(0.42, 0, 0.22, 1);
const smooth = (f: number, a: number, b: number, from = 0, to = 1) => interpolate(f, [a, Math.max(a + 1, b)], [from, to], { ...clamp, easing: ease });
const polar = (cx: number, cy: number, r: number, deg: number) => ({ x: cx + Math.cos(deg * Math.PI / 180) * r, y: cy + Math.sin(deg * Math.PI / 180) * r });
const arc = (cx: number, cy: number, r: number, from: number, to: number) => { const a = polar(cx, cy, r, from); const b = polar(cx, cy, r, to); return 'M ' + a.x + ' ' + a.y + ' A ' + r + ' ' + r + ' 0 ' + (to - from > 180 ? 1 : 0) + ' 1 ' + b.x + ' ' + b.y; };

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (index: number, fallback: number) => {
    const found = cues.find((c) => c.wordIndex === index || c.index === index) || cues[index];
    return typeof found?.startFrame === 'number' ? found.startFrame : fallback;
  };
  const cueEnd = (index: number, fallback: number) => {
    const found = cues.find((c) => c.wordIndex === index || c.index === index) || cues[index];
    return typeof found?.endFrame === 'number' ? found.endFrame : fallback;
  };
  const fly = cue(8, 171);
  const bullets = cue(10, 214);
  const lift = cue(11, 236);
  const car = cue(13, 280);
  const computer = cue(17, 367);
  const smarter = cue(18, 389);
  const humansEnd = cueEnd(21, 477);
  const basically = cue(22, 518);
  const iron = cue(23, 545);
  const man = cue(24, 572);
  const manEnd = cueEnd(24, 598);
  const weird = cue(28, 668);
  const partEnd = cueEnd(29, 710);
  const already = cue(31, 743);
  const have = cue(32, 767);
  const pieces = cue(33, 791);
  const piecesEnd = cueEnd(33, 814);
  const technology = cue(36, 863);
  const inventoryEnd = cueEnd(36, 886);
  const separation = smooth(frame, pieces, piecesEnd);
  const inventory = smooth(frame, pieces, inventoryEnd);
  const available = smooth(frame, already, have + 18);
  const traceExit = smooth(frame, weird, piecesEnd);
  const schematic = smooth(frame, 7, 80);
  const reveal = spring({ frame: frame - 3, fps, config: { stiffness: 160, damping: 14, mass: 0.28 } });
  const coreScale = interpolate(reveal, [0, 1], [0.74, 1]);
  const coreOpacity = smooth(frame, 3, 10);
  const armorOpacity = smooth(frame, 12, fly) * (1 - inventory * 0.61);
  const faceOpacity = smooth(frame, 36, fly);
  const titleOpacity = smooth(frame, basically, basically + 16);
  const kickerOpacity = smooth(frame, pieces, pieces + 15);
  const titleY = interpolate(spring({ frame: frame - basically, fps, config: { stiffness: 160, damping: 14, mass: 0.65 } }), [0, 1], [15, 0]);

  const keys = [
    { f: 0, z: 3.8, x: 960, y: 620 },
    { f: 18, z: 3.8, x: 960, y: 620 },
    { f: fly, z: 2.1, x: 960, y: 445 },
    { f: fly + 17, z: 2.1, x: 905, y: 446 },
    { f: bullets, z: 2.1, x: 905, y: 446 },
    { f: bullets + 17, z: 2.1, x: 1038, y: 448 },
    { f: lift, z: 2.1, x: 1038, y: 448 },
    { f: car, z: 1.88, x: 910, y: 605 },
    { f: computer, z: 1.88, x: 910, y: 605 },
    { f: smarter + 4, z: 1.88, x: 1040, y: 601 },
    { f: humansEnd, z: 1.88, x: 1040, y: 601 },
    { f: basically, z: 1.88, x: 1040, y: 601 },
    { f: manEnd, z: 1, x: 960, y: 540 },
    { f: weird, z: 1, x: 960, y: 540 },
    { f: partEnd, z: 1.24, x: 1045, y: 558 },
    { f: pieces, z: 1.24, x: 1045, y: 558 },
    { f: piecesEnd, z: 1.14, x: 1075, y: 550 },
    { f: inventoryEnd, z: 1, x: 960, y: 540 },
    { f: Math.max(durationInFrames, inventoryEnd + 1), z: 1, x: 960, y: 540 }
  ];
  const orderedKeys = keys.map((k, i, all) => ({ ...k, f: i === 0 ? k.f : Math.max(k.f, all[i - 1].f + 0.01) }));
  let camera = orderedKeys[orderedKeys.length - 1];
  for (let i = 0; i < orderedKeys.length - 1; i++) {
    const a = orderedKeys[i];
    const b = orderedKeys[i + 1];
    if (frame <= b.f) {
      const t = smooth(frame, a.f, b.f);
      camera = { f: frame, z: a.z + (b.z - a.z) * t, x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
      break;
    }
  }

  const capabilities: Capability[] = [
    { key: 'flight', label: 'flight', at: fly, side: -1, lower: false, x: 510, y: 388, plateWidth: 280, path: arc(960, 545, 253, 202, 247), connector: 'M 790 422 H 818 L 842 429', dx: -84, dy: -22 },
    { key: 'protection', label: 'protection', at: bullets, side: 1, lower: false, x: 1130, y: 388, plateWidth: 310, path: arc(960, 545, 253, 293, 338), connector: 'M 1130 422 H 1102 L 1078 429', dx: 84, dy: -22 },
    { key: 'strength', label: 'strength', at: lift, side: -1, lower: true, x: 510, y: 704, plateWidth: 280, path: arc(960, 545, 253, 113, 158), connector: 'M 790 738 H 819 L 842 756', dx: -84, dy: 26 },
    { key: 'computing', label: 'computing', at: computer, side: 1, lower: true, x: 1130, y: 704, plateWidth: 310, path: arc(960, 545, 253, 22, 67), connector: 'M 1130 738 H 1101 L 1078 756', dx: 84, dy: 26 }
  ];
  const bracketOpacity = smooth(frame, weird, weird + 18);
  const endNoteOpacity = smooth(frame, piecesEnd, piecesEnd + 24);
  const stageScale = Math.min(width / 1920, height / 1080);

  return (
    <AbsoluteFill style={{ backgroundColor: C.bg, overflow: 'hidden', color: C.white, fontFamily: 'IBM Plex Sans, sans-serif' }}>
      <div style={{ position: 'absolute', width: 1920, height: 1080, left: (width - 1920 * stageScale) / 2, top: (height - 1080 * stageScale) / 2, transform: 'scale(' + stageScale + ')', transformOrigin: '0 0', overflow: 'hidden', background: 'radial-gradient(ellipse at 50% 53%, #1A282F 0%, #10191F 61%, #0D151A 100%)' }}>
        <div style={{ position: 'absolute', left: 140, top: 95, width: 1640, height: 890, overflow: 'hidden', borderRadius: 3, border: '1px solid rgba(101,117,124,0.19)', boxSizing: 'border-box', background: 'radial-gradient(ellipse at 50% 51%, rgba(43,57,63,0.34), rgba(16,25,31,0) 68%)', boxShadow: '0 22px 110px rgba(0,0,0,0.18)' }}>
          <div style={{ position: 'absolute', left: -140, top: -95, width: 1920, height: 1080, transformOrigin: '0 0', transform: 'translate(960px, 540px) scale(' + camera.z + ') translate(' + (-camera.x) + 'px, ' + (-camera.y) + 'px)', willChange: 'transform' }}>
            <svg width="1920" height="1080" viewBox="0 0 1920 1080" style={{ position: 'absolute', inset: 0, opacity: schematic }} aria-hidden="true">
              <g stroke={C.slate} strokeWidth="1" fill="none" opacity="0.17">
                <path d="M 240 305 H 1680 M 240 855 H 1680 M 960 238 V 290 M 960 852 V 910 M 398 308 V 850 M 1522 308 V 850" />
                <path d="M 240 322 V 305 H 257 M 1663 305 H 1680 V 322 M 240 838 V 855 H 257 M 1663 855 H 1680 V 838" />
                <path d="M 304 540 H 354 M 329 515 V 565 M 1566 540 H 1616 M 1591 515 V 565" />
                <path d="M 690 264 H 735 M 1185 264 H 1230 M 690 894 H 735 M 1185 894 H 1230" />
              </g>
              <g stroke={C.slate} strokeWidth="1.25" opacity="0.35">
                {Array.from({ length: 48 }, (_, i) => {
                  const deg = i * 7.5;
                  const a = polar(960, 545, i % 4 === 0 ? 284 : 289, deg);
                  const b = polar(960, 545, 296, deg);
                  return <line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} />;
                })}
              </g>
              <g fill="none" stroke={C.slate} strokeWidth="1" opacity={0.25 * (1 - inventory * 0.4)}>
                <path d={arc(960, 545, 276, 4, 82)} />
                <path d={arc(960, 545, 276, 98, 177)} />
                <path d={arc(960, 545, 276, 184, 262)} />
                <path d={arc(960, 545, 276, 278, 356)} />
              </g>
            </svg>

            <div style={{ position: 'absolute', left: 810, top: 470, width: 300, height: 300, borderRadius: '50%', background: 'radial-gradient(circle, rgba(186,147,76,0.075) 0%, rgba(186,147,76,0.027) 36%, rgba(186,147,76,0) 68%)', opacity: coreOpacity * (1 - inventory * 0.7), transform: 'scale(' + coreScale + ')' }} />

            <svg width="640" height="660" viewBox="0 0 640 660" aria-label="Iconic mask and chest armor with a circular core" style={{ position: 'absolute', left: 640, top: 240, overflow: 'visible' }}>
              <path d="M 256 54 L 384 54 L 408 86 L 417 186 L 394 239 L 358 271 L 282 271 L 246 239 L 223 186 L 232 86 Z" fill="#343127" stroke={C.brass} strokeWidth="3" strokeLinejoin="round" opacity={armorOpacity} />
              <path d="M 263 74 L 377 74 L 391 104 L 384 145 L 393 182 L 372 227 L 347 247 L 293 247 L 268 227 L 247 182 L 256 145 L 249 104 Z" fill={C.brass} fillOpacity="0.88" stroke="#D7B772" strokeOpacity="0.65" strokeWidth="1.5" strokeLinejoin="round" opacity={armorOpacity} />
              <path d="M 260 155 L 301 164 L 303 174 L 267 169 Z" fill={C.white} opacity={faceOpacity * (1 - inventory * 0.56)} />
              <path d="M 380 155 L 339 164 L 337 174 L 373 169 Z" fill={C.white} opacity={faceOpacity * (1 - inventory * 0.56)} />
              <path d="M 260 282 L 290 304 L 350 304 L 380 282 L 457 294 L 533 354 L 505 452 L 442 535 L 375 580 L 265 580 L 198 535 L 135 452 L 107 354 L 183 294 Z" fill="#272A27" stroke={C.brass} strokeWidth="3" strokeLinejoin="round" opacity={armorOpacity} />
              <path d="M 187 311 L 247 305 L 274 326 L 227 355 L 148 374 L 130 357 Z" fill={C.brass} fillOpacity="0.27" stroke={C.brass} strokeWidth="1.5" strokeLinejoin="round" opacity={armorOpacity} />
              <path d="M 453 311 L 393 305 L 366 326 L 413 355 L 492 374 L 510 357 Z" fill={C.brass} fillOpacity="0.27" stroke={C.brass} strokeWidth="1.5" strokeLinejoin="round" opacity={armorOpacity} />
              <path d="M 166 403 L 223 416 L 264 469 L 301 493 L 297 556 L 224 515 L 188 463 Z" fill={C.brass} fillOpacity="0.15" stroke={C.brass} strokeOpacity="0.66" strokeWidth="1.5" strokeLinejoin="round" opacity={armorOpacity} />
              <path d="M 474 403 L 417 416 L 376 469 L 339 493 L 343 556 L 416 515 L 452 463 Z" fill={C.brass} fillOpacity="0.15" stroke={C.brass} strokeOpacity="0.66" strokeWidth="1.5" strokeLinejoin="round" opacity={armorOpacity} />
              <circle cx="320" cy="380" r="68" fill={C.bg} stroke={inventory > 0.985 ? C.white : C.brass} strokeWidth="8" strokeOpacity={1 - inventory * 0.25} opacity={coreOpacity} style={{ transformOrigin: '320px 380px', transform: 'scale(' + coreScale + ')' }} />
              <circle cx="320" cy="380" r="51" fill="none" stroke={C.white} strokeOpacity={0.78 - inventory * 0.16} strokeWidth="2" opacity={coreOpacity} style={{ transformOrigin: '320px 380px', transform: 'scale(' + coreScale + ')' }} />
              <circle cx="320" cy="380" r="38" fill={C.white} fillOpacity={0.94 - inventory * 0.1} stroke={C.raised} strokeOpacity="0.6" strokeWidth="1" opacity={coreOpacity} style={{ transformOrigin: '320px 380px', transform: 'scale(' + coreScale + ')' }} />
            </svg>

            <svg width="1920" height="1080" viewBox="0 0 1920 1080" style={{ position: 'absolute', inset: 0, opacity: smooth(frame, 8, 36) }} aria-hidden="true">
              <g fill="none" strokeWidth="3" strokeLinecap="butt">
                {[[-74, -21], [9, 64], [94, 150], [180, 232], [257, 268]].map((segment, i) => <path key={i} d={arc(960, 620, 96, segment[0], segment[1])} stroke={C.slate} opacity={0.47 + traceExit * 0.35} />)}
              </g>
              <g stroke={C.white} strokeWidth="1.2" opacity="0.3">
                <path d="M 960 507 V 516 M 960 724 V 733 M 847 620 H 856 M 1064 620 H 1073" />
              </g>
              <g fill="none" stroke={C.brass} strokeWidth="2" strokeDasharray="5 7" opacity={(1 - traceExit) * 0.5}>
                <path d="M 868 587 L 804 545 V 462" />
                <path d="M 1052 587 L 1116 545 V 462" />
                <path d="M 875 666 L 812 704" />
                <path d="M 1045 666 L 1108 704" />
              </g>
              <g stroke={C.coral} fill="none" strokeWidth="2.5" opacity={bracketOpacity}>
                <path d={'M ' + (1083 + separation * 7) + ' 533 H ' + (1063 + separation * 7) + ' V 569 H ' + (1083 + separation * 7)} />
                <path d={'M ' + (1131 + separation * 24) + ' 533 H ' + (1151 + separation * 24) + ' V 569 H ' + (1131 + separation * 24)} />
                <path d={'M ' + (1106 + separation * 15) + ' 532 V 522 H ' + (1204 + separation * 32)} strokeWidth="1.25" opacity="0.65" />
              </g>
            </svg>

            {capabilities.map((cap) => {
              const enter = spring({ frame: frame - cap.at, fps, config: { stiffness: 160, damping: 14, mass: 0.55 } });
              const alpha = smooth(frame, cap.at, cap.at + 9);
              const drawing = smooth(frame, cap.at, cap.at + 22);
              const next = cap.key === 'flight' ? bullets : cap.key === 'protection' ? lift : cap.key === 'strength' ? computer : basically;
              const active = smooth(frame, cap.at, cap.at + 9) * (1 - smooth(frame, next, next + 14));
              const dx = cap.dx * separation;
              const dy = cap.dy * separation + (1 - enter) * (cap.lower ? 16 : -16);
              const settledColor = available > 0.5 ? C.teal : C.brass;
              return (
                <div key={cap.key} style={{ position: 'absolute', inset: 0, opacity: alpha, transform: 'translate(' + dx + 'px, ' + dy + 'px)' }}>
                  <svg width="1920" height="1080" viewBox="0 0 1920 1080" style={{ position: 'absolute', inset: 0 }} aria-hidden="true">
                    <path d={cap.path} fill="none" stroke={C.brass} strokeWidth="10" strokeLinecap="butt" pathLength="1" strokeDasharray="1" strokeDashoffset={1 - drawing} opacity={0.8 * (1 - available)} />
                    <path d={cap.path} fill="none" stroke={C.teal} strokeWidth="10" strokeLinecap="butt" pathLength="1" strokeDasharray="1" strokeDashoffset={1 - drawing} opacity={available} />
                    <path d={cap.connector} fill="none" stroke={settledColor} strokeWidth="2" opacity="0.65" pathLength="1" strokeDasharray="1" strokeDashoffset={1 - drawing} />
                  </svg>
                  <div style={{ position: 'absolute', left: cap.x, top: cap.y, width: cap.plateWidth, height: 68, transform: 'scaleX(' + interpolate(enter, [0, 1], [0.86, 1]) + ')', transformOrigin: cap.side === -1 ? 'right center' : 'left center', background: 'linear-gradient(105deg, #1E2B31, #18242A)', border: '1px solid ' + (available > 0.5 ? 'rgba(20,125,135,0.75)' : 'rgba(186,147,76,0.6)'), boxSizing: 'border-box', boxShadow: '0 9px 25px rgba(0,0,0,0.15)', display: 'flex', alignItems: 'center', paddingLeft: 24 }}>
                    <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 4, backgroundColor: C.brass, opacity: 1 - available }} />
                    <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 4, backgroundColor: C.teal, opacity: available }} />
                    <div style={{ position: 'absolute', inset: 0, backgroundColor: C.brass, opacity: active * 0.075 * (1 - available) }} />
                    <span style={{ fontFamily: 'IBM Plex Sans, sans-serif', fontWeight: 500, fontSize: 30, letterSpacing: '-0.45px', lineHeight: 1, color: C.white }}>{cap.label}</span>
                    <div style={{ position: 'absolute', right: 19, top: 28, width: 10, height: 10, borderRadius: '50%', background: C.brass, opacity: 0.8 * (1 - available) }} />
                    <div style={{ position: 'absolute', right: 19, top: 28, width: 10, height: 10, borderRadius: '50%', background: C.teal, opacity: available }} />
                    <div style={{ position: 'absolute', inset: -7, border: '1px solid rgba(186,147,76,0.33)', clipPath: 'polygon(0 0, 22px 0, 22px 2px, 2px 2px, 2px 20px, 0 20px, 0 0, 100% 0, 100% 20px, calc(100% - 2px) 20px, calc(100% - 2px) 2px, calc(100% - 22px) 2px, calc(100% - 22px) 0, 100% 0, 100% 100%, calc(100% - 22px) 100%, calc(100% - 22px) calc(100% - 2px), calc(100% - 2px) calc(100% - 2px), calc(100% - 2px) calc(100% - 20px), 100% calc(100% - 20px), 100% 100%, 0 100%, 0 calc(100% - 20px), 2px calc(100% - 20px), 2px calc(100% - 2px), 22px calc(100% - 2px), 22px 100%, 0 100%)', opacity: active * (1 - available), pointerEvents: 'none' }} />
                  </div>
                  <div style={{ position: 'absolute', left: cap.x + 2, top: cap.y + 80, display: 'flex', alignItems: 'center', gap: 9, opacity: endNoteOpacity, fontFamily: 'IBM Plex Mono, monospace', fontSize: 17, letterSpacing: '1.8px', color: C.white, fontVariantNumeric: 'tabular-nums' }}>
                    <span style={{ display: 'block', width: 14, height: 3, backgroundColor: C.teal }} />
                    EXISTING PIECE
                  </div>
                </div>
              );
            })}

            <div style={{ position: 'absolute', left: 1216 + separation * 32, top: 508, opacity: bracketOpacity, fontFamily: 'IBM Plex Mono, monospace', fontSize: 19, letterSpacing: '1.1px', lineHeight: 1, color: C.coral }}>INTEGRATION GAP</div>
            <div style={{ position: 'absolute', left: 797, top: 881, width: 326, height: 41, opacity: endNoteOpacity, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 12, borderTop: '1px solid rgba(101,117,124,0.45)', color: C.slate, fontFamily: 'IBM Plex Mono, monospace', fontSize: 18, letterSpacing: '2.1px' }}>
              <span style={{ display: 'inline-block', width: 6, height: 6, background: C.coral }} />
              NOT AN INTEGRATED SUIT
            </div>
          </div>
        </div>

        <div style={{ position: 'absolute', left: 96, top: 96, width: 640, height: 143, padding: '0 16px 12px 0', boxSizing: 'border-box', opacity: titleOpacity, transform: 'translateY(' + titleY + 'px)', background: 'linear-gradient(90deg, rgba(16,25,31,0.98) 0%, rgba(16,25,31,0.91) 76%, rgba(16,25,31,0) 100%)' }}>
          <div style={{ position: 'absolute', top: 0, left: 0, width: 34, height: 3, backgroundColor: C.brass, opacity: 1 - inventory }} />
          <div style={{ position: 'absolute', top: 0, left: 0, width: 34, height: 3, backgroundColor: C.teal, opacity: inventory }} />
          <div style={{ position: 'absolute', left: 0, top: 17, color: C.white, opacity: kickerOpacity, fontFamily: 'IBM Plex Sans, sans-serif', fontSize: 24, lineHeight: 1.2, fontWeight: 400, whiteSpace: 'nowrap' }}>pieces of this technology.</div>
          <div style={{ position: 'absolute', left: 0, top: 52, fontFamily: 'Manrope, sans-serif', fontWeight: 600, fontSize: 54, lineHeight: 1.13, letterSpacing: '-2px', whiteSpace: 'nowrap' }}>
            <span>Basically,</span><span style={{ opacity: smooth(frame, iron, iron + 9) }}> Iron</span><span style={{ opacity: smooth(frame, man, man + 9) }}> Man.</span>
          </div>
        </div>

        <div style={{ position: 'absolute', right: 163, bottom: 112, opacity: smooth(frame, basically, manEnd), display: 'flex', alignItems: 'center', gap: 21, fontFamily: 'IBM Plex Mono, monospace', fontSize: 15, letterSpacing: '1.5px', color: C.slate }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: 9 }}><span style={{ width: 17, height: 3, background: C.brass }} />CINEMATIC IDEAL</span>
          <span style={{ display: 'flex', alignItems: 'center', gap: 9, opacity: available }}><span style={{ width: 17, height: 3, background: C.teal }} />AVAILABLE PIECES</span>
        </div>
        <div style={{ position: 'absolute', left: 140, top: 95, width: 1640, height: 890, pointerEvents: 'none', boxShadow: 'inset 0 0 90px rgba(8,13,17,0.22)' }} />
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { index?: number; wordIndex?: number; globalIndex?: number; id?: string | number; word?: string; text?: string; startFrame?: number; endFrame?: number };
type ShotProps = { wordCues?: WordCue[] };
type Point = { x: number; y: number };
type NodeSpec = { id: string; label: string; x: number; y: number; w: number; h: number; path: Point[]; duration: number };

const C = { bg: '#F3F1EB', white: '#FFFFFF', ink: '#17262C', slate: '#65757C', teal: '#147D87', coral: '#E96B53', line: '#D6DEDA', grid: '#AEBBB7' };
const F = { display: 'Manrope, sans-serif', sans: 'IBM Plex Sans, sans-serif', mono: 'IBM Plex Mono, monospace' };
const CLAMP = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
const CORE = { x: 978, y: 554 };
const NODES: NodeSpec[] = [
  { id: 'weapons', label: 'weapons', x: 280, y: 322, w: 294, h: 112, path: [{ x: 977, y: 553 }, { x: 827, y: 549 }, { x: 755, y: 378 }, { x: 574, y: 378 }], duration: 172 },
  { id: 'flight', label: 'flight systems', x: 1326, y: 322, w: 324, h: 112, path: [{ x: 977, y: 553 }, { x: 1149, y: 553 }, { x: 1151, y: 378 }, { x: 1326, y: 378 }], duration: 147 },
  { id: 'armor', label: 'armor', x: 233, y: 535, w: 284, h: 112, path: [{ x: 977, y: 553 }, { x: 804, y: 553 }, { x: 719, y: 591 }, { x: 517, y: 591 }], duration: 157 },
  { id: 'sensors', label: 'sensors', x: 1382, y: 535, w: 286, h: 112, path: [{ x: 977, y: 553 }, { x: 1146, y: 553 }, { x: 1203, y: 591 }, { x: 1382, y: 591 }], duration: 168 },
  { id: 'motors', label: 'motors', x: 300, y: 758, w: 286, h: 112, path: [{ x: 977, y: 553 }, { x: 804, y: 553 }, { x: 783, y: 814 }, { x: 586, y: 814 }], duration: 181 },
  { id: 'computers', label: 'computers', x: 1306, y: 758, w: 324, h: 112, path: [{ x: 977, y: 553 }, { x: 1145, y: 553 }, { x: 1103, y: 814 }, { x: 1306, y: 814 }], duration: 193 }
];

const pathD = (p: Point[]) => 'M ' + p[0].x + ' ' + p[0].y + ' C ' + p[1].x + ' ' + p[1].y + ' ' + p[2].x + ' ' + p[2].y + ' ' + p[3].x + ' ' + p[3].y;
const pointAt = (p: Point[], t: number): Point => { const a = 1 - t; return { x: a * a * a * p[0].x + 3 * a * a * t * p[1].x + 3 * a * t * t * p[2].x + t * t * t * p[3].x, y: a * a * a * p[0].y + 3 * a * a * t * p[1].y + 3 * a * t * t * p[2].y + t * t * t * p[3].y }; };
const tangentAt = (p: Point[], t: number) => { const a = 1 - t; return Math.atan2(3 * a * a * (p[1].y - p[0].y) + 6 * a * t * (p[2].y - p[1].y) + 3 * t * t * (p[3].y - p[2].y), 3 * a * a * (p[1].x - p[0].x) + 6 * a * t * (p[2].x - p[1].x) + 3 * t * t * (p[3].x - p[2].x)) * 180 / Math.PI; };
const returnPath = (n: NodeSpec): Point[] => n.path.map((p) => ({ x: p.x, y: p.y + (n.id === 'weapons' || n.id === 'flight' ? -13 : 13) }));
const clean = (v: unknown) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueFor = (index: number, word: string) => {
    const tagged = cues.find((q) => Number(q.wordIndex ?? q.globalIndex ?? q.index ?? String(q.id ?? '').replace(/^W/i, '')) === index);
    if (tagged) return tagged;
    const local = cues[index - 37];
    if (local && clean(local.word ?? local.text) === clean(word)) return local;
    return cues.find((q) => clean(q.word ?? q.text) === clean(word));
  };
  const start = (index: number, word: string, fallback: number) => cueFor(index, word)?.startFrame ?? fallback;
  const end = (index: number, word: string, fallback: number) => cueFor(index, word)?.endFrame ?? fallback;
  const tFirst = start(48, 'first', 214);
  const tProblem = start(49, 'problem', 237);
  const tClose = end(55, 'one', 395);
  const tPower = start(56, 'Power', 413);
  const tPowerDone = end(56, 'Power', 437);
  const tIron = start(57, 'Iron', 440);
  const tFlying = start(63, 'flying', 587);
  const tComputer = start(64, 'supercomputer', 612);
  const tComputerDone = end(64, 'supercomputer', 636);
  const tWrapped = start(65, 'wrapped', 637);
  const tBodyDone = end(69, 'body', 759);
  const tAll = start(71, 'all', 807);
  const tThatDone = end(73, 'that', 866);
  const tNeeds = start(74, 'needs', 865);
  const tEnergy = start(75, 'energy', 885);
  const tEnergyDone = end(75, 'energy', 904);
  const tA = start(76, 'A', 914);
  const tLot = start(77, 'lot', 930);
  const tOf = start(78, 'of', 946);
  const tFinalEnergy = start(79, 'energy', 962);
  const tEnd = end(79, 'energy', 979);
  const f = Math.min(frame, tEnd, durationInFrames - 1);
  const lerp = (t: number, a: number, b: number, u: number, v: number) => interpolate(t, [a, Math.max(a + 1, b)], [u, v], CLAMP);
  const ease = (a: number, b: number, u = 0, v = 1) => interpolate(f, [a, Math.max(a + 1, b)], [u, v], { ...CLAMP, easing: Easing.inOut(Easing.cubic) });
  const ramp = (a: number, b: number) => lerp(f, a, b, 0, 1);
  const entrance = spring({ frame: Math.max(0, f - 2), fps, durationInFrames: 30, config: { stiffness: 160, damping: 18, mass: 0.56 } });
  const coreScale = f < 2 ? 0.93 : 0.93 + entrance * 0.07;
  const peripheralEntrance = ramp(2, 32);
  const power = ease(tPower, tPowerDone);
  const problemFocus = ease(tProblem, tClose);
  const flightT = ramp(tIron, tFlying);
  const computerT = ramp(tIron, tComputer);
  const flightPoint = pointAt(NODES[1].path, flightT);
  const computerPoint = pointAt(NODES[5].path, computerT);
  const localTravel = ease(tFlying, tComputer);
  const pullback = ease(tWrapped, tBodyDone);
  const widen = ease(tAll, tThatDone);
  const finalPush = ease(tFinalEnergy, tEnd);
  let zoom = 1;
  let focusX = CORE.x;
  let focusY = CORE.y;
  let anchorX = CORE.x;
  let anchorY = CORE.y;
  if (f >= tFirst && f < tIron) {
    const p = ease(tFirst, tClose);
    zoom = 1 + 0.48 * p;
    anchorX = CORE.x + 67 * p;
    anchorY = CORE.y + 12 * p;
  } else if (f >= tIron && f < tFlying) {
    const p = ease(tIron, tFlying);
    focusX = flightPoint.x;
    focusY = flightPoint.y;
    zoom = 1.48 - 0.21 * p;
    anchorX = 1045 + 95 * p;
    anchorY = 566 - 40 * p;
  } else if (f >= tFlying && f < tWrapped) {
    const dest = pointAt(NODES[5].path, lerp(f, tFlying, tComputer, (tFlying - tIron) / Math.max(1, tComputer - tIron), 1));
    focusX = 1326 + (dest.x - 1326) * localTravel;
    focusY = 378 + (dest.y - 378) * localTravel;
    zoom = 1.27 - 0.03 * localTravel;
    anchorX = 1140;
    anchorY = 526 + 104 * localTravel;
  } else if (f >= tWrapped) {
    focusX = 1306 + (CORE.x - 1306) * pullback;
    focusY = 814 + (CORE.y - 814) * pullback;
    zoom = 1.24 - 0.28 * pullback;
    anchorX = 1140 + (CORE.x - 1140) * pullback;
    anchorY = 630 + (CORE.y - 630) * pullback;
    zoom -= 0.02 * widen;
    zoom += 0.06 * finalPush;
  }
  const tx = anchorX - focusX * zoom;
  const ty = anchorY - focusY * zoom;
  const routeReveal = ramp(tPowerDone, tIron + 36);
  const traffic = ramp(tIron, tIron + 28);
  const demand = 0.16 * ease(tPowerDone, tIron + 40) + 0.16 * ease(tFlying, tComputerDone) + 0.25 * widen + 0.18 * ease(tEnergy, tEnergyDone) + 0.25 * ease(tLot, tEnd);
  const constraint = 0.25 * power + 0.25 * widen + 0.22 * ease(tEnergy, tEnergyDone) + 0.28 * ease(tFinalEnergy, tEnd);
  const meterAlpha = 0.72 * ramp(tPower, tPowerDone) + 0.28 * widen;
  const regularFlowAlpha = ramp(tComputerDone, tBodyDone);
  const flightFocus = ramp(tFlying, tFlying + 10) * (1 - ramp(tComputer, tComputer + 22));
  const computerFocus = ramp(tComputer, tComputer + 10) * (1 - ramp(tWrapped, tBodyDone));
  const headingAlpha = ramp(tPower, tPower + 12);
  const boardScale = Math.min(width / 1920, height / 1080);
  const meterX = 904;
  const meterY = 670;
  const kickerWords = [{ text: 'A', at: tA }, { text: 'lot', at: tLot }, { text: 'of', at: tOf }, { text: 'energy.', at: tFinalEnergy }];

  const packet = (n: NodeSpec, t: number, alpha: number, key: string, lead = false) => {
    const p = pointAt(n.path, Math.max(0, Math.min(1, t)));
    const angle = tangentAt(n.path, Math.max(0, Math.min(1, t)));
    return <g key={key} opacity={alpha} transform={'translate(' + p.x + ' ' + p.y + ') rotate(' + angle + ')'}><rect x={lead ? -24 : -17} y={-5} width={lead ? 39 : 29} height={10} rx={5} fill={C.teal} opacity={0.065} /><rect x={lead ? -16 : -11} y={-2.7} width={lead ? 24 : 17} height={5.4} rx={2.7} fill={C.teal} /><circle cx={lead ? 7 : 5} cy={0} r={2} fill={C.white} opacity={0.9} /></g>;
  };

  return <AbsoluteFill style={{ backgroundColor: C.bg, overflow: 'hidden', color: C.ink, fontFamily: F.sans }}>
    <div style={{ position: 'absolute', width: 1920, height: 1080, left: (width - 1920 * boardScale) / 2, top: (height - 1080 * boardScale) / 2, transform: 'scale(' + boardScale + ')', transformOrigin: '0 0' }}>
      <div style={{ position: 'absolute', inset: 0, background: 'radial-gradient(ellipse at 69% 49%, rgba(20,125,135,0.035), transparent 61%)' }} />
      <div style={{ position: 'absolute', width: 1920, height: 1080, transform: 'translate(' + tx + 'px,' + ty + 'px) scale(' + zoom + ')', transformOrigin: '0 0', willChange: 'transform' }}>
        <div style={{ position: 'absolute', left: 130, top: 90, width: 1660, height: 900, borderRadius: 30, overflow: 'hidden', border: '1px solid rgba(101,117,124,0.18)', backgroundColor: '#F8F7F2', boxShadow: '0 12px 44px rgba(23,38,44,0.025)' }}>
          <div style={{ position: 'absolute', inset: 0, background: 'radial-gradient(ellipse at 51% 48%, rgba(255,255,255,0.97) 0%, rgba(243,247,242,0.5) 45%, rgba(243,241,235,0.18) 85%)' }} />
          <svg width={1660} height={900} viewBox='0 0 1660 900' style={{ position: 'absolute', inset: 0 }}>
            <defs><pattern id='s02-mesh' width={48} height={48} patternUnits='userSpaceOnUse'><path d='M 48 0 L 0 0 0 48' fill='none' stroke={C.grid} strokeWidth={0.7} opacity={0.22} /><path d='M 0 45 L 0 51 M -3 48 L 3 48' fill='none' stroke={C.slate} strokeWidth={0.7} opacity={0.2} /></pattern></defs>
            <rect width={1660} height={900} fill='url(#s02-mesh)' />
            <path d='M 24 43 V 24 H 43 M 1617 24 H 1636 V 43 M 24 857 V 876 H 43 M 1617 876 H 1636 V 857' fill='none' stroke={C.slate} strokeWidth={1.4} opacity={0.32} />
          </svg>
        </div>

        <svg width={1920} height={1080} viewBox='0 0 1920 1080' style={{ position: 'absolute', inset: 0, overflow: 'visible' }}>
          <defs>
            <mask id='s02-conduits' maskUnits='userSpaceOnUse' x={0} y={0} width={1920} height={1080}>
              <rect width={1920} height={1080} fill='white' />
              <rect x={818} y={477} width={302} height={154} rx={77} fill='black' />
              {NODES.map((n) => <rect key={n.id} x={n.x} y={n.y} width={n.w} height={n.h} rx={n.h / 2} fill='black' />)}
            </mask>
          </defs>
          <g mask='url(#s02-conduits)'>
            {NODES.map((n) => <g key={'route-' + n.id}>
              <path d={pathD(n.path)} fill='none' stroke={C.teal} strokeWidth={12} opacity={0.018 + 0.024 * demand} />
              <path d={pathD(n.path)} fill='none' stroke={C.line} strokeWidth={2} opacity={0.5 + 0.5 * peripheralEntrance} />
              <path d={pathD(returnPath(n))} fill='none' stroke={C.slate} strokeWidth={0.9} opacity={0.13 + 0.17 * demand} />
              <path d={pathD(n.path)} pathLength={1} strokeDasharray='1 1' strokeDashoffset={1 - routeReveal} fill='none' stroke={C.teal} strokeWidth={1.7} opacity={0.5 * power} />
            </g>)}
            {NODES.map((n, ni) => {
              const shift = random('shot02-route-' + n.id) * n.duration;
              return <g key={'traffic-' + n.id}>
                {Array.from({ length: 7 }, (_, j) => {
                  const threshold = j * 0.135;
                  const capacity = j === 0 ? 1 : interpolate(demand, [threshold, threshold + 0.13], [0, 1], CLAMP);
                  const elapsed = Math.max(0, f - tIron) + shift + j * n.duration / 7;
                  const t = (elapsed % n.duration) / n.duration;
                  const fade = interpolate(t, [0, 0.07, 0.92, 1], [0, 1, 1, 0], CLAMP);
                  return packet(n, t, traffic * regularFlowAlpha * capacity * fade * 0.8, 'p-' + ni + '-' + j);
                })}
                {Array.from({ length: 5 }, (_, j) => {
                  const capacity = interpolate(demand, [0.12 + j * 0.15, 0.29 + j * 0.15], [0, 1], CLAMP);
                  const loop = n.duration * 1.45;
                  const t = 1 - ((Math.max(0, f - tIron) + shift + j * loop / 5) % loop) / loop;
                  const p = pointAt(returnPath(n), t);
                  const fade = interpolate(t, [0, 0.08, 0.94, 1], [0, 1, 1, 0], CLAMP);
                  return <circle key={'return-' + ni + '-' + j} cx={p.x} cy={p.y} r={3.6} fill='#F8F7F2' stroke={C.slate} strokeWidth={1} opacity={fade * capacity * regularFlowAlpha * 0.66} />;
                })}
              </g>;
            })}
            {packet(NODES[1], flightT, traffic * (1 - ramp(tFlying, tFlying + 14)), 'flight-lead', true)}
            {packet(NODES[5], computerT, traffic * (1 - ramp(tComputer, tComputer + 14)), 'computer-lead', true)}
          </g>
          <path d='M 979 641 L 979 654' fill='none' stroke={C.coral} strokeWidth={1.2} opacity={meterAlpha * 0.55} />
          {[{ n: NODES[1], at: tFlying }, { n: NODES[5], at: tComputer }].map(({ n, at }) => {
            const a = ramp(at, at + 25);
            return <circle key={'arrival-' + n.id} cx={n.path[3].x} cy={n.path[3].y} r={5 + a * 20} fill='none' stroke={C.teal} strokeWidth={1.4} opacity={(f >= at ? 1 : 0) * (1 - a) * 0.7} />;
          })}
        </svg>

        {NODES.map((n) => {
          const focus = n.id === 'flight' ? flightFocus : n.id === 'computers' ? computerFocus : 0;
          const emphasis = Math.max(focus, 0.22 * widen);
          return <div key={'pill-' + n.id} style={{ position: 'absolute', left: n.x, top: n.y, width: n.w, height: n.h, borderRadius: n.h / 2, background: C.white, border: '1px solid rgba(101,117,124,' + (0.18 + 0.14 * emphasis) + ')', boxSizing: 'border-box', opacity: 0.68 + 0.32 * peripheralEntrance, transform: 'translateY(' + (1 - peripheralEntrance) * 5 + 'px)', boxShadow: '0 5px 18px rgba(23,38,44,0.035)', display: 'flex', alignItems: 'center', padding: '0 30px', gap: 19 }}>
            <div style={{ position: 'absolute', inset: -6, borderRadius: 66, border: '1.5px solid ' + C.teal, opacity: focus * 0.6 }} />
            <span style={{ width: 11, height: 11, flexShrink: 0, borderRadius: '50%', border: '1.4px solid ' + C.teal, background: power > 0 ? C.teal : 'transparent', opacity: 0.34 + 0.55 * power }} />
            <span style={{ fontFamily: F.sans, fontWeight: 500, fontSize: 30, color: C.ink, letterSpacing: -0.6, whiteSpace: 'nowrap' }}>{n.label}</span>
          </div>;
        })}

        <div style={{ position: 'absolute', left: 818, top: 477, width: 302, height: 154, boxSizing: 'border-box', borderRadius: 77, background: 'rgba(255,255,255,0.97)', border: '1px solid rgba(101,117,124,0.25)', boxShadow: '0 6px 24px rgba(23,38,44,0.055)', transform: 'scale(' + coreScale + ')', transformOrigin: '160px 77px' }}>
          <div style={{ position: 'absolute', inset: -7, borderRadius: 85, border: '1px solid ' + C.coral, opacity: 0.09 * constraint }} />
          <div style={{ position: 'absolute', left: 31, top: 52, opacity: power, transform: 'translateY(' + 5 * (1 - power) + 'px)', fontSize: 32, fontFamily: F.display, fontWeight: 600, letterSpacing: -1 }}>Power</div>
          <svg width={302} height={154} viewBox='0 0 302 154' style={{ position: 'absolute', inset: 0, overflow: 'visible' }}>
            <g transform={'translate(' + (-76 * (1 - power)) + ' 0)'}>
              <circle cx={236} cy={77} r={56} fill={C.bg} opacity={0.72} />
              <circle cx={236} cy={77} r={56} fill='none' stroke={C.slate} strokeWidth={1} strokeDasharray='1 9' opacity={0.22 * (1 - power)} />
              <circle cx={236} cy={77} r={48} fill='none' stroke={C.teal} strokeWidth={3.6} pathLength={100} strokeDasharray='76 24' strokeLinecap='round' transform='rotate(-45 236 77)' opacity={0.68 * (1 - power)} />
              <circle cx={236} cy={77} r={37} fill='none' stroke={C.slate} strokeWidth={1.2} pathLength={100} strokeDasharray='61 39' transform='rotate(92 236 77)' opacity={0.42 * (1 - power)} />
              <path d='M 229 77 H 243 M 236 70 V 84' fill='none' stroke={C.slate} strokeWidth={1} opacity={0.3 * (1 - power)} />
              <circle cx={236} cy={77} r={48} fill={C.white} opacity={power} />
              <circle cx={236} cy={77} r={48} fill='none' stroke={C.coral} strokeWidth={3.6 + 0.6 * constraint} pathLength={100} strokeDasharray='100 100' strokeDashoffset={100 * (1 - power)} transform='rotate(-90 236 77)' opacity={power} />
              <circle cx={236} cy={77} r={36} fill={C.coral} opacity={power * (0.085 + 0.045 * constraint)} />
              <circle cx={236} cy={77} r={11 + 3 * power} fill={C.coral} opacity={power} />
              <circle cx={236} cy={77} r={56} fill='none' stroke={C.coral} strokeWidth={0.9} opacity={constraint * 0.3} />
            </g>
          </svg>
        </div>

        <svg width={1920} height={1080} viewBox='0 0 1920 1080' style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }}>
          <path d='M 806 503 V 465 H 844 M 1094 465 H 1132 V 503 M 806 605 V 643 H 844 M 1094 643 H 1132 V 605' fill='none' stroke={power > 0.5 ? C.coral : C.slate} strokeWidth={1.1} opacity={problemFocus * (0.24 - 0.1 * pullback) + finalPush * 0.13} />
        </svg>

        <div style={{ position: 'absolute', left: meterX, top: meterY, width: 160, opacity: meterAlpha }}>
          <div style={{ fontFamily: F.mono, fontSize: 22, color: C.slate, letterSpacing: -0.6, lineHeight: '30px', marginBottom: 8 }}>demand</div>
          <div style={{ display: 'flex', gap: 4, alignItems: 'flex-end', height: 31 }}>
            {Array.from({ length: 12 }, (_, i) => {
              const a = interpolate(demand, [i / 12, (i + 0.8) / 12], [0, 1], CLAMP);
              return <div key={'meter-' + i} style={{ position: 'relative', width: 9, height: 17 + i * 1.2, borderRadius: 2, background: '#DEE3DE', overflow: 'hidden' }}><div style={{ position: 'absolute', inset: 0, background: i > 8 ? C.coral : C.teal, opacity: a * (i > 8 ? 0.95 : 0.8), transform: 'scaleY(' + a + ')', transformOrigin: 'bottom' }} /></div>;
            })}
          </div>
          <div style={{ marginTop: 8, width: 152, height: 1, background: '#D6DDD8' }} />
        </div>
        <div style={{ position: 'absolute', left: 184, top: 936, fontFamily: F.mono, fontSize: 19, letterSpacing: 0.1, color: C.slate, opacity: 0.78 }}>schematic — not measured</div>
      </div>

      <div style={{ position: 'absolute', left: 130, top: 90, width: 880, height: 213, borderTopLeftRadius: 30, background: 'linear-gradient(180deg, rgba(248,247,242,0.99) 0%, rgba(248,247,242,0.98) 75%, rgba(248,247,242,0) 100%)', opacity: headingAlpha, pointerEvents: 'none' }} />
      {f >= tPower && <div style={{ position: 'absolute', left: 176, top: 145, width: 650, opacity: headingAlpha, transform: 'translateY(' + (1 - headingAlpha) * 8 + 'px)' }}>
        <div style={{ display: 'flex', gap: 7, height: 31, marginBottom: 7, fontFamily: F.display, fontSize: 24, lineHeight: '31px', fontWeight: 600, color: C.slate, letterSpacing: -0.45 }}>
          {kickerWords.map((w, i) => <span key={i} style={{ display: 'inline-block', opacity: ramp(w.at, w.at + 7), transform: 'translateY(' + 4 * (1 - ramp(w.at, w.at + 7)) + 'px)' }}>{w.text}</span>)}
        </div>
        <h1 style={{ margin: 0, fontFamily: F.display, fontSize: 56, fontWeight: 600, lineHeight: '66px', letterSpacing: -2.3, color: C.ink }}>Power.</h1>
      </div>}
    </div>
  </AbsoluteFill>;
};

import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

const C = { paper: "#F3F1EB", white: "#FFFFFF", ink: "#17262C", slate: "#65757C", teal: "#147D87", coral: "#E96B53", brass: "#BA934C", line: "#DADFD9" };
const FONT = { display: "Manrope, Arial, sans-serif", sans: "IBM Plex Sans, Arial, sans-serif", mono: "IBM Plex Mono, monospace" };
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const smooth = { ...clamp, easing: Easing.inOut(Easing.cubic) };
type Cue = { wordIndex?: number; index?: number; word?: string; text?: string; startFrame?: number; endFrame?: number };
type ShotProps = { wordCues?: Cue[] };
type Pose = { t: number; z: number; x: number; y: number };

// Consolidate coincident timestamps before interpolation. The last pose at a
// timestamp wins, so inputRange is always strictly increasing, including f244.
const samplePose = (frame: number, poses: Pose[]) => {
  const sorted = poses.filter((p) => Number.isFinite(p.t)).slice().sort((a, b) => a.t - b.t);
  const unique: Pose[] = [];
  sorted.forEach((pose) => {
    if (unique.length && unique[unique.length - 1].t === pose.t) unique[unique.length - 1] = pose;
    else unique.push(pose);
  });
  if (!unique.length) return { z: 1, x: 0, y: 0 };
  if (unique.length === 1) return { z: unique[0].z, x: unique[0].x, y: unique[0].y };
  const times = unique.map((p) => p.t);
  return {
    z: interpolate(frame, times, unique.map((p) => p.z), smooth),
    x: interpolate(frame, times, unique.map((p) => p.x), smooth),
    y: interpolate(frame, times, unique.map((p) => p.y), smooth),
  };
};

const Pill = ({ text, color, background }: { text: string; color: string; background: string }) => (
  <div style={{ height: 34, padding: "0 12px", borderRadius: 5, background, color, display: "flex", alignItems: "center", gap: 8, fontFamily: FONT.mono, fontSize: 18, fontWeight: 600, letterSpacing: 1.2, whiteSpace: "nowrap" }}>
    <span style={{ width: 6, height: 6, borderRadius: "50%", background: color }} />{text}
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueFrame = (index: number, fallback: number, edge: "startFrame" | "endFrame" = "startFrame") => {
    const explicit = cues.find((cue) => cue.wordIndex === index || cue.index === index);
    const positional = cues.length >= 112 ? cues[index] : cues.length === 32 ? cues[index - 80] : undefined;
    const value = (explicit || positional)?.[edge];
    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
  };
  const t = {
    batteries: cueFrame(82, 41), batteriesEnd: cueFrame(82, 64, "endFrame"),
    fuel: cueFrame(83, 64), cells: cueFrame(84, 87), cellsEnd: cueFrame(84, 110, "endFrame"),
    tiny: cueFrame(87, 156), jet: cueFrame(88, 178), engines: cueFrame(89, 201), enginesEnd: cueFrame(89, 224, "endFrame"),
    but: cueFrame(90, 244), nothing: cueFrame(91, 269), small: cueFrame(92, 293), enoughEnd: cueFrame(93, 342, "endFrame"),
    power: cueFrame(95, 368), iron: cueFrame(96, 392), man: cueFrame(97, 417),
    weapons: cueFrame(98, 442), flight: cueFrame(99, 467), systems: cueFrame(100, 491), armor: cueFrame(101, 516),
    sensors: cueFrame(102, 541), computers: cueFrame(103, 566), motors: cueFrame(105, 615), motorsEnd: cueFrame(105, 639, "endFrame"),
    for: cueFrame(106, 640), useful: cueFrame(108, 690), amount: cueFrame(109, 714), of: cueFrame(110, 739), time: cueFrame(111, 764), timeEnd: cueFrame(111, 788, "endFrame"),
  };
  const fade = (start: number, length = 14) => interpolate(frame, [start, start + Math.max(1, length)], [0, 1], clamp);
  const reveal = (start: number) => frame < start ? 0 : spring({ frame: frame - start, fps, config: { stiffness: 160, damping: 14, mass: 0.7 } });
