import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = {
  wordIndex?: number;
  index?: number;
  id?: string | number;
  word?: string;
  text?: string;
  startFrame?: number;
  endFrame?: number;
};

type ShotProps = { wordCues?: WordCue[] };
type Point = { x: number; y: number };

const COLORS = {
  paper: "#F3F1EB",
  white: "#FFFFFF",
  ink: "#17262C",
  slate: "#65757C",
  teal: "#147D87",
  coral: "#E96B53",
  guide: "#DCE1DE"
};
const SANS = "'IBM Plex Sans', Arial, sans-serif";
const MONO = "'IBM Plex Mono', monospace";
const DISPLAY = "'Manrope', 'IBM Plex Sans', sans-serif";
const CURVE_START = { x: 360, y: 748 };
const CURVE_C1 = { x: 760, y: 728 };
const CURVE_C2 = { x: 1160, y: 454 };
const CURVE_END = { x: 1560, y: 356 };
const BASELINE = 866;
const JUNCTION = { x: 960, y: 620 };
const CURVE_PATH = "M 360 748 C 760 728 1160 454 1560 356";

function curvePoint(t: number): Point {
  const u = 1 - t;
  return {
    x: u * u * u * CURVE_START.x + 3 * u * u * t * CURVE_C1.x + 3 * u * t * t * CURVE_C2.x + t * t * t * CURVE_END.x,
    y: u * u * u * CURVE_START.y + 3 * u * u * t * CURVE_C1.y + 3 * u * t * t * CURVE_C2.y + t * t * t * CURVE_END.y
  };
}

function curveSection(a: number, b: number, steps = 72): string {
  return Array.from({ length: steps + 1 }, (_, i) => {
    const p = curvePoint(a + (b - a) * i / steps);
    return (i === 0 ? "M " : "L ") + p.x.toFixed(2) + " " + p.y.toFixed(2);
  }).join(" ");
}

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, 804, durationInFrames - 1);
  const ease = Easing.inOut(Easing.cubic);
  const tween = (value: number, start: number, end: number, from = 0, to = 1) => interpolate(value, [start, Math.max(start + 1, end)], [from, to], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
  const at = (index: number, fallback: number) => {
    const exact = cues.find((cue) => cue.wordIndex === index || cue.index === index || cue.id === index || cue.id === "W" + index);
    const positional = cues.length === 33 ? cues[index - 112] : undefined;
    const match = exact || positional;
    return typeof match?.startFrame === "number" && Number.isFinite(match.startFrame) ? match.startFrame : fallback;
  };
  const problem = at(116, 108);
  const heavy = at(118, 176);
  const add = at(119, 209);
  const enough = at(120, 230);
  const batteries = at(121, 251);
  const fly = at(123, 293);
  const long = at(126, 356);
  const time = at(127, 377);
  const added = at(130, 440);
  const much = at(132, 482);
  const weight = at(133, 503);
  const that = at(134, 524);
  const you = at(135, 544);
  const need = at(136, 565);
  const even = at(137, 586);
  const more = at(138, 607);
  const energy = at(139, 628);
  const just = at(140, 649);
  const carry = at(142, 691);
  const finalBatteries = at(144, 733);

  const massProgress = interpolate(f, [0, heavy, add, batteries, fly, long, time + 21, added, much, weight, that], [0.075, 0.075, 0.17, 0.29, 0.42, 0.55, 0.67, 0.73, 0.84, 0.88, 0.88], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
  const point = curvePoint(massProgress);
  const finalPoint = curvePoint(0.88);
  const initialPoint = curvePoint(0.075);
  const blockBottom = point.y + 280;
  const chartReveal = tween(f, 3, problem + 27);
  const gridReveal = tween(f, 12, problem + 27);
  const badgeSpring = spring({ frame: f - 3, fps, config: { stiffness: 160, damping: 14, mass: 0.85 } });
  const badgeOpacity = tween(f, 3, 13);
  const weightLock = tween(f, weight, weight + 12);
  const feedbackReveal = tween(f, that, energy + 16);
  const junctionReveal = tween(f, need, even + 12);
  const energyReveal = tween(f, even, energy + 12);
  const resolve = tween(f, finalBatteries, 754);
  const introPull = tween(f, 18, problem + 27);
  const tracking = tween(f, heavy, batteries + 18);

  let zoom = 1.7 + (1 - 1.7) * introPull;
  let focusX = initialPoint.x + (960 - initialPoint.x) * introPull;
  let focusY = initialPoint.y + (620 - initialPoint.y) * introPull;
  if (f >= heavy) {
    zoom = 1 + 0.14 * tracking;
    focusX = 960 + (point.x - 90 - 960) * tracking * 0.52;
    focusY = 620 + (point.y + 86 - 620) * tracking * 0.65;
  }
  const trackedX = 960 + (finalPoint.x - 90 - 960) * 0.52;
  const trackedY = 620 + (finalPoint.y + 86 - 620) * 0.65;
  if (f >= that) {
    const followReturn = tween(f, that, even);
    zoom = 1.14 + 0.05 * followReturn;
    focusX = trackedX + (1110 - trackedX) * followReturn;
    focusY = trackedY + (655 - trackedY) * followReturn;
  }
  if (f >= even) {
    const inspectLoop = tween(f, even, just);
    zoom = 1.19 + 0.31 * inspectLoop;
    focusX = 1110 + (JUNCTION.x - 1110) * inspectLoop;
    focusY = 655 + (JUNCTION.y - 655) * inspectLoop;
  }
  if (f >= just) {
    const pullOut = tween(f, just, 754);
    zoom = 1.5 - 0.5 * pullOut;
    focusX = JUNCTION.x;
    focusY = JUNCTION.y;
  }
  const panX = 960 - focusX * zoom;
  const panY = 620 - focusY * zoom;
  const activePath = curveSection(Math.max(0, massProgress - 0.19), massProgress);
