import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; word?: string; text?: string; startFrame?: number };
type ShotProps = { wordCues?: WordCue[] };

const INK = "#17262C";
const SLATE = "#65757C";
const TEAL = "#147D87";
const CORAL = "#E96B53";
const PAPER = "#F3F1EB";
const SANS = "IBM Plex Sans, Arial, sans-serif";
const MONO = "IBM Plex Mono, monospace";
const STAGE_W = 1660;
const STAGE_H = 900;
const ease = Easing.inOut(Easing.cubic);
const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
const lerp = (a: number, b: number, progress: number) => a + (b - a) * progress;
const range = (frame: number, start: number, end: number, from = 0, to = 1) => interpolate(frame, [start, Math.max(start + 1, end)], [from, to], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });

function makeWave(frame: number, startX: number, endX: number, baseline: number, amplitude: number, control: boolean): string {
  const count = 112;
  return Array.from({ length: count + 1 }, (_, index) => {
    const t = index / count;
    const envelope = Math.pow(Math.sin(Math.PI * t), 0.65);
    const wave = control
      ? Math.sin(t * Math.PI * 6.4 + frame * 0.023) * 0.7 + Math.sin(t * Math.PI * 13.2 - frame * 0.011) * 0.23
      : Math.sin(t * Math.PI * 25 + frame * 0.07) * 0.63 + Math.sin(t * Math.PI * 41 - frame * 0.035) * 0.3;
    const x = lerp(startX, endX, t);
    const y = baseline + wave * amplitude * envelope;
    return `${index === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`;
  }).join(" ");
}

