export const GeneratedShot: React.FC<ShotProps> = (props) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (index: number, fallback: number) => {
    const match = cues.find((item) => item.wordIndex === index || item.index === index) || (cues.length === 29 ? cues[index - 145] : undefined);
    return typeof match?.startFrame === "number" ? match.startFrame : fallback;
  };
  const t = {
    congratulations: cue(145, 0), youve: cue(146, 66), created: cue(147, 93),
    very: cue(149, 147), expensive: cue(150, 174), flying: cue(151, 200), battery: cue(152, 227),
    then: cue(153, 271), flight: cue(155, 324), real: cue(156, 358), exist: cue(160, 466),
    but: cue(161, 493), ridiculous: cue(163, 548), loud: cue(164, 575), dangerous: cue(165, 602),
    difficult: cue(166, 629), control: cue(168, 683), limited: cue(171, 765), time: cue(173, 819)
  };
  const f = Math.min(frame, durationInFrames - 1, 892);
  const batteryEnd = t.battery + 26;
  const wideEnd = Math.min(845, t.time + 26);
  const collapseEnd = t.flight + 26;
  const collapse = range(f, t.then, collapseEnd);
  const boardAlpha = range(f, t.then + 7, t.flight + 26);
  const settle = spring({ frame: Math.max(0, f - 3), fps, config: { mass: 1.65, stiffness: 160, damping: 22 } });
  const hover = range(f, t.flying, batteryEnd, 0, 24);
  const batteryTop = 141 + (1 - settle) * 65 - hover;
  const batteryLeft = 615;
  const gaugeX = batteryLeft + 215;
  const gaugeY = batteryTop + 166;
  const tabCenterX = 167;
  const tabCenterY = 127;
  const batteryDX = (tabCenterX - gaugeX) * collapse;
  const batteryDY = (tabCenterY - gaugeY) * collapse;
  const batteryScale = lerp(1, 0.09, collapse);
  const plumeBaseline = batteryTop + 602;
  const datumY = 750;
  const baselineY = lerp(plumeBaseline, 495, range(f, t.then + 8, collapseEnd));
  const pullback = range(f, t.youve, batteryEnd);
  let zoom = lerp(2.35, 1, pullback);
  let focusX = gaugeX;
  let focusY = lerp(gaugeY + 15, 450, pullback);

  const cameraKeys = [
    { at: t.then, z: 1, x: 830, y: 450 },
    { at: collapseEnd, z: 1, x: 830, y: 450 },
    { at: t.loud, z: 1, x: 830, y: 450 },
    { at: t.loud + 17, z: 1.28, x: 660, y: 480 },
    { at: t.dangerous, z: 1.28, x: 660, y: 480 },
    { at: t.dangerous + 17, z: 1.28, x: 755, y: 480 },
    { at: t.difficult, z: 1.28, x: 755, y: 480 },
    { at: t.difficult + 20, z: 1.31, x: 951, y: 488 },
    { at: t.control, z: 1.31, x: 951, y: 488 },
    { at: t.control + 22, z: 1.62, x: 988, y: 495 },
    { at: t.limited, z: 1.62, x: 988, y: 495 },
    { at: t.limited + 22, z: 1.3, x: 995, y: 490 },
    { at: t.time, z: 1.3, x: 995, y: 490 },
    { at: wideEnd, z: 1, x: 830, y: 450 }
  ];
  if (f >= t.then) {
    const last = cameraKeys[cameraKeys.length - 1];
    zoom = last.z;
    focusX = last.x;
    focusY = last.y;
    for (let index = 0; index < cameraKeys.length - 1; index++) {
      const a = cameraKeys[index];
      const b = cameraKeys[index + 1];
      if (f >= a.at && f < b.at) {
        const p = range(f, a.at, b.at);
        zoom = lerp(a.z, b.z, p);
        focusX = lerp(a.x, b.x, p);
        focusY = lerp(a.y, b.y, p);
        break;
      }
    }
  }
  const panX = STAGE_W / 2 - focusX * zoom;
  const panY = STAGE_H / 2 - focusY * zoom;
  const reticleTransfer = range(f, t.then, collapseEnd);
  const finalWaypoint = range(f, t.time, wideEnd);
  const junctionX = lerp(998, 830, finalWaypoint);
  const reticleX = lerp(gaugeX, junctionX, reticleTransfer);
  const reticleY = lerp(gaugeY, 495, reticleTransfer);
  const reticleSize = lerp(101, 70, reticleTransfer);
  const reticleColor = f >= wideEnd ? SLATE : TEAL;
  const inspectionFreeze = Math.min(f, t.time);
  const waveform = makeWave(inspectionFreeze, 201, 457, 495, 66, false);
  const controlWave = makeWave(inspectionFreeze, 870, 1115, 495, 60, true);
  const endurance = range(f, t.limited, wideEnd, 246, 48);
  const lanes = [
    { x: 175, title: "loud", start: t.loud, end: t.dangerous, id: "01" },
    { x: 509, title: "dangerous", start: t.dangerous, end: t.difficult, id: "02" },
    { x: 843, title: "difficult to control", start: t.difficult, end: t.limited, id: "03" },
    { x: 1177, title: "limited flight time", start: t.limited, end: t.time, id: "04" }
  ];
  const dangerReveal = range(f, t.dangerous, t.dangerous + 16);
  const controlReveal = range(f, t.difficult, t.difficult + 19);
  const expenseAlpha = range(f, t.very, t.expensive + 9) * (1 - range(f, t.then, t.then + 20));
  const titleAlpha = range(f, 3, 18);
  const tabAlpha = range(f, t.then + 30, collapseEnd);
  const actualScale = Math.min(width / 1920, height / 1080);

  return (
    <AbsoluteFill style={{ backgroundColor: PAPER, color: INK, overflow: "hidden", fontFamily: SANS }}>
      <div style={{ position: "absolute", left: (width - 1920 * actualScale) / 2, top: (height - 1080 * actualScale) / 2, width: 1920, height: 1080, transform: `scale(${actualScale})`, transformOrigin: "0 0" }}>
        <div style={{ position: "absolute", left: 130, top: 150, width: STAGE_W, height: STAGE_H, overflow: "hidden", borderRadius: 22, backgroundColor: "#FAF9F5", border: "1px solid #DDDCD4", boxShadow: "0 16px 44px rgba(23,38,44,0.045)" }}>
          <div style={{ position: "absolute", inset: 0, opacity: 0.5, backgroundImage: "radial-gradient(circle, #CFD4CF 1px, transparent 1px)", backgroundSize: "36px 36px" }} />
          <div style={{ position: "absolute", left: 0, top: 0, width: STAGE_W, height: STAGE_H, transform: `translate(${panX}px, ${panY}px) scale(${zoom})`, transformOrigin: "0 0" }}>
