type WordCue = { wordIndex?: number; index?: number; id?: number | string; word?: string; text?: string; startFrame?: number; endFrame?: number };
type ShotProps = { wordCues?: WordCue[] };
type Point = { x: number; y: number };

const C = { paper: "#F3F1EB", white: "#FFFFFF", ink: "#17262C", slate: "#65757C", teal: "#147D87", coral: "#E96B53", brass: "#BA934C" };
const sans = "IBM Plex Sans, Arial, sans-serif";
const mono = "IBM Plex Mono, monospace";
const display = "Manrope, Arial, sans-serif";
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const ease = Easing.inOut(Easing.cubic);
const DEFAULT_WORDS = ["Iron", "Man", "casually", "flies", "through", "cities", "stops", "in", "midair", "changes", "direction", "instantly", "and", "lands", "like", "he's", "stepping", "out", "of", "an", "elevator"];
const DEFAULT_FRAMES = [0, 21, 47, 72, 98, 124, 149, 175, 200, 226, 251, 277, 302, 328, 354, 379, 405, 430, 456, 481, 507];
const ROUTE: Point[] = [{ x: 130, y: 322 }, { x: 215, y: 322 }, { x: 215, y: 196 }, { x: 354, y: 196 }, { x: 432, y: 196 }, { x: 432, y: 388 }, { x: 548, y: 388 }];
const ROUTE_D = "M130 322 H215 V196 H354 H432 V388 H548";
const SEGMENTS = ROUTE.slice(1).map((p, i) => Math.hypot(p.x - ROUTE[i].x, p.y - ROUTE[i].y));
const TOTAL_LENGTH = SEGMENTS.reduce((sum, length) => sum + length, 0);
const HOVER_DISTANCE = SEGMENTS[0] + SEGMENTS[1] + SEGMENTS[2];
const TURN_DISTANCE = HOVER_DISTANCE + SEGMENTS[3];
const LOWER_DISTANCE = TURN_DISTANCE + SEGMENTS[4];

function pointOnRoute(distance: number): Point {
  let remaining = Math.max(0, Math.min(TOTAL_LENGTH, distance));
  for (let i = 0; i < SEGMENTS.length; i++) {
    if (remaining <= SEGMENTS[i]) {
      const t = remaining / SEGMENTS[i];
      return { x: ROUTE[i].x + (ROUTE[i + 1].x - ROUTE[i].x) * t, y: ROUTE[i].y + (ROUTE[i + 1].y - ROUTE[i].y) * t };
    }
    remaining -= SEGMENTS[i];
  }
  return ROUTE[ROUTE.length - 1];
}

function TraceReticle({ x, y, radius = 27, color = C.teal }: { x: number; y: number; radius?: number; color?: string }) {
  return <g transform={`translate(${x} ${y})`} fill="none" stroke={color} strokeWidth={1.5}>
    <circle r={radius} opacity={0.75} />
    <circle r={radius - 7} opacity={0.25} />
    <path d={`M${-radius - 8} 0 H-10 M10 0 H${radius + 8} M0 ${-radius - 8} V-10 M0 10 V${radius + 8}`} />
    <circle r={3} fill={color} stroke="none" />
  </g>;
}

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
