  const cues = props.wordCues || [];
  const normalize = (text: string) => text.toLowerCase().replace(/[^a-z0-9]/g, "");
  const cueFrame = (index: number) => {
    const offset = index - 174;
    const direct = cues.find((cue) => cue.wordIndex === index || cue.index === index || cue.id === index || cue.id === `W${index}`);
    const textMatch = cues.find((cue) => normalize(cue.word || cue.text || "") === normalize(DEFAULT_WORDS[offset]));
    const found = direct || textMatch;
    return found && typeof found.startFrame === "number" ? found.startFrame : DEFAULT_FRAMES[offset];
