type WordCue = { wordIndex?: number; index?: number; startFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };

const C = {
  paper: "#F3F1EB",
  white: "#FFFFFF",
  ink: "#17262C",
  slate: "#65757C",
  teal: "#147D87",
  coral: "#E96B53",
  brass: "#BA934C",
  dark: "#10191F"
};
const sans = "'IBM Plex Sans', Arial, sans-serif";
const mono = "'IBM Plex Mono', monospace";
const ease = Easing.inOut(Easing.cubic);
const clampOptions = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const normalize = (value: string) => value.toLowerCase().replace(/[^a-z']/g, "");

const CornerOutline: React.FC<{ color: string; width: number; height: number; opacity?: number }> = ({ color, width, height, opacity = 1 }) => (
  <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ position: "absolute", inset: 0, overflow: "visible", opacity }}>
    <path d={`M 0 25 V 0 H 25 M ${width - 25} 0 H ${width} V 25 M ${width} ${height - 25} V ${height} H ${width - 25} M 25 ${height} H 0 V ${height - 25}`} fill="none" stroke={color} strokeWidth={3} strokeLinecap="square" />
  </svg>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (index: number, fallback: number, word: string) => {
    const exact = cues.find((item) => item.wordIndex === index || item.index === index);
    const ordinal = cues.length === 33 ? cues[index - 195] : undefined;
    const lexical = cues.find((item) => normalize(item.word || item.text || "") === normalize(word));
    return exact?.startFrame ?? ordinal?.startFrame ?? lexical?.startFrame ?? fallback;
  };
  const humanAt = cue(195, 0, "Human");
  const thatAt = cue(200, 113, "that");
  const thrustAt = cue(205, 229, "thrust");
  const yourAt = cue(206, 257, "Your");
  const bodyAt = cue(207, 282, "body");
  const accelerationAt = cue(214, 453, "acceleration");
  const organsAt = cue(216, 519, "organs");
  const advancedAt = cue(220, 606, "advanced");
  const suitAt = cue(222, 649, "suit");
  const theyAt = cue(224, 710, "They");
  const physicsAt = cue(227, 782, "physics");
  const ramp = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { ...clampOptions, easing: ease });
  const reveal = spring({ frame: frame - 2, fps, durationInFrames: 18, config: { stiffness: 160, damping: 14, mass: 0.7 } });
  const assemblyOpacity = interpolate(frame, [2, 8], [0, 1], clampOptions);
  const establish = ramp(humanAt + 20, thatAt + 23);
  const maneuver = ramp(thrustAt, thrustAt + 48);
  const turn = ramp(accelerationAt, accelerationAt + 24);
  const push = ramp(yourAt, accelerationAt + 24);
  const accelerationPush = ramp(accelerationAt, accelerationAt + 24);
  const pull = ramp(theyAt, physicsAt + 24);
  const elaborate = ramp(advancedAt, suitAt + 22);
  const baseZoom = 1.68 - 0.68 * establish;
  const closeZoom = baseZoom + 0.31 * push + 0.24 * accelerationPush;
  const zoom = closeZoom * (1 - pull) + pull;
  const centerX = 900;
  const centerY = 528;
  const assemblyX = 84 * maneuver;
  const assemblyY = -22 * maneuver;
  const occupantX = centerX + assemblyX + 23;
  const occupantY = centerY + assemblyY + 35;
  const cameraX = (centerX + assemblyX * 0.88 + 23 * push) * (1 - pull) + 900 * pull;
  const cameraY = (centerY + assemblyY * 0.88 + 35 * push) * (1 - pull) + 528 * pull;
  const focus = ramp(bodyAt, bodyAt + 18);
  const inspection = ramp(accelerationAt, accelerationAt + 18);
  const bodySteady = ramp(organsAt, organsAt + 18);
  const traceOpacity = ramp(thrustAt, thrustAt + 9) * (1 - 0.67 * pull);
  const headingOpacity = interpolate(frame, [2, 12], [0, 1], clampOptions);
  const finalEmphasis = ramp(physicsAt, physicsAt + 16);
  const stageFade = interpolate(frame, [0, 8], [0.94, 1], clampOptions);
  const arrivalScale = 0.91 + 0.09 * reveal;
  const outerLeft = centerX + assemblyX - 261;
  const outerTop = centerY + assemblyY - 168;
  const arrowX = interpolate(turn, [0, 1], [1245, 1328], clampOptions);
  const arrowY = interpolate(turn, [0, 1], [580, 390], clampOptions);
  const arrowAngle = interpolate(turn, [0, 1], [-18, -87], clampOptions);
  const progress = interpolate(frame, [0, Math.max(1, durationInFrames - 1)], [0, 1], clampOptions);

  return (
    <AbsoluteFill style={{ backgroundColor: C.dark, overflow: "hidden", color: C.ink, fontFamily: sans }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * Math.min(width / 1920, height / 1080)) / 2, top: (height - 1080 * Math.min(width / 1920, height / 1080)) / 2, transform: `scale(${Math.min(width / 1920, height / 1080)})`, transformOrigin: "top left" }}>
        <div style={{ position: "absolute", left: 130, top: 90, width: 1660, height: 900, backgroundColor: C.paper, borderRadius: 4, overflow: "hidden", opacity: stageFade, boxShadow: "0 28px 90px rgba(0,0,0,0.25)" }}>
          <div style={{ position: "absolute", inset: 0, backgroundImage: "linear-gradient(rgba(23,38,44,0.025) 1px, transparent 1px), linear-gradient(90deg, rgba(23,38,44,0.025) 1px, transparent 1px)", backgroundSize: "60px 60px", opacity: 0.8 }} />
          <div style={{ position: "absolute", width: 1660, height: 900, transformOrigin: "0 0", transform: `translate(900px, 528px) scale(${zoom}) translate(${-cameraX}px, ${-cameraY}px)` }}>
            <svg width="1660" height="900" viewBox="0 0 1660 900" style={{ position: "absolute", inset: 0, overflow: "visible" }}>
              <defs>
                <mask id="shot07-maneuver-mask" maskUnits="userSpaceOnUse" x="1050" y="325" width="345" height="365">
                  <path d="M 1080 626 C 1145 624 1224 606 1270 552 C 1320 493 1328 442 1328 370" fill="none" stroke="white" strokeWidth="20" pathLength="1" strokeDasharray="1" strokeDashoffset={1 - maneuver} />
                </mask>
              </defs>
              <circle cx={centerX} cy={centerY} r="350" fill="rgba(255,255,255,0.4)" stroke={C.ink} strokeOpacity={0.17 + 0.15 * pull} strokeWidth="1.5" />
              <circle cx={centerX} cy={centerY} r="337" fill="none" stroke={C.ink} strokeOpacity="0.065" strokeWidth="1" />
              <circle cx={centerX} cy={centerY} r="357" fill="none" stroke={C.coral} strokeOpacity={0.32 * pull} strokeWidth="2" strokeDasharray={`${2244 * pull} 2244`} transform={`rotate(-90 ${centerX} ${centerY})`} />
              {Array.from({ length: 48 }, (_, i) => {
                const angle = (i / 48) * Math.PI * 2;
                const major = i % 4 === 0;
                const inner = major ? 337 : 343;
                return <line key={i} x1={centerX + Math.cos(angle) * inner} y1={centerY + Math.sin(angle) * inner} x2={centerX + Math.cos(angle) * 350} y2={centerY + Math.sin(angle) * 350} stroke={C.ink} strokeWidth={major ? 1.5 : 1} strokeOpacity={major ? 0.3 : 0.12} />;
              })}
              <path d="M 900 153 V 169 M 900 887 V 899 M 525 528 H 541 M 1259 528 H 1275" fill="none" stroke={C.ink} strokeOpacity="0.32" strokeWidth="1.5" />
              <path d="M 550 528 H 1250 M 900 178 V 878" fill="none" stroke={C.ink} strokeOpacity="0.07" strokeWidth="1" strokeDasharray="3 9" />
              <g opacity={traceOpacity}>
                <path d="M 1080 626 C 1145 624 1224 606 1270 552 C 1320 493 1328 442 1328 370" fill="none" stroke={C.brass} strokeWidth="3" mask="url(#shot07-maneuver-mask)" />
                <path d="M 1245 580 C 1306 526 1328 459 1328 390" fill="none" stroke={C.coral} strokeWidth="4" pathLength="1" strokeDasharray="1" strokeDashoffset={1 - turn} />
                <g transform={`translate(${arrowX} ${arrowY}) rotate(${arrowAngle})`} opacity={ramp(thrustAt + 13, thrustAt + 27)}>
                  <path d="M -25 0 H 1 M -9 -9 L 2 0 L -9 9" fill="none" stroke={turn > 0.02 ? C.coral : C.brass} strokeWidth="3.5" strokeLinecap="square" strokeLinejoin="miter" />
                </g>
              </g>
            </svg>

            <div style={{ position: "absolute", left: outerLeft, top: outerTop + 12 * (1 - reveal), width: 522, height: 336, opacity: assemblyOpacity, transform: `scale(${arrivalScale})`, transformOrigin: "50% 50%" }}>
              <div style={{ position: "absolute", inset: 0, backgroundColor: C.white, border: `3px solid ${C.brass}`, borderRadius: 5, boxShadow: "0 12px 28px rgba(23,38,44,0.075)" }} />
              <div style={{ position: "absolute", left: 23, top: 18, fontFamily: sans, fontSize: 29, fontWeight: 600, color: C.brass, lineHeight: 1.2 }}>suit</div>
              <div style={{ position: "absolute", left: 91, right: 24, top: 35, height: 1, backgroundColor: C.brass, opacity: 0.45 }} />
              <div style={{ position: "absolute", inset: 12, border: `1px solid ${C.brass}`, borderRadius: 2, opacity: 0.56 * elaborate }} />
              <div style={{ position: "absolute", left: 20, right: 20, top: 61, height: 1, backgroundColor: C.brass, opacity: 0.6 * elaborate, transform: `scaleX(${elaborate})`, transformOrigin: "left center" }} />
              <div style={{ position: "absolute", left: 20, right: 20, bottom: 20, height: 1, backgroundColor: C.brass, opacity: 0.6 * elaborate, transform: `scaleX(${elaborate})`, transformOrigin: "right center" }} />
              <div style={{ position: "absolute", left: 22, top: 75, bottom: 34, width: 1, backgroundColor: C.brass, opacity: 0.45 * elaborate }} />
              <div style={{ position: "absolute", right: 22, top: 75, bottom: 34, width: 1, backgroundColor: C.brass, opacity: 0.45 * elaborate }} />
              <svg width="522" height="336" style={{ position: "absolute", inset: 0, opacity: elaborate }}>
                <path d="M 12 77 H 34 M 12 259 H 34 M 488 77 H 510 M 488 259 H 510 M 108 12 V 25 M 415 12 V 25 M 108 311 V 324 M 415 311 V 324" fill="none" stroke={C.brass} strokeWidth="1.5" />
              </svg>
              <div style={{ position: "absolute", left: 93, top: 83, width: 382, height: 240, borderRadius: 3, backgroundColor: C.ink, border: `2px solid ${C.coral}`, boxShadow: "0 8px 20px rgba(23,38,44,0.12)", display: "flex", alignItems: "center", justifyContent: "center" }}>
                <div style={{ position: "absolute", top: 20, left: 20, width: 22, height: 3, backgroundColor: C.coral, opacity: 0.65 + 0.35 * inspection }} />
                <div style={{ fontFamily: sans, color: C.paper, fontWeight: 600, fontSize: 49, letterSpacing: -1.7, lineHeight: 1.1, whiteSpace: "nowrap" }}>Your body</div>
                <div style={{ position: "absolute", left: 21, right: 21, bottom: 22, height: 1, backgroundColor: C.paper, opacity: 0.08 + 0.07 * bodySteady }} />
              </div>
            </div>

            <div style={{ position: "absolute", left: occupantX - 202, top: occupantY - 132, width: 404, height: 264, opacity: focus, pointerEvents: "none" }}>
              <mg.FocusFrame color={C.coral} style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} />
              <CornerOutline color={C.coral} width={404} height={264} opacity={0.75 + 0.25 * inspection} />
            </div>

            <div style={{ position: "absolute", left: 1310, top: 330, color: C.coral, fontFamily: sans, fontSize: 27, fontWeight: 500, whiteSpace: "nowrap", opacity: inspection * (1 - push * 0.7) * (1 - pull) }}>acceleration</div>
          </div>

          <div style={{ position: "absolute", left: 45, top: 35, width: 1140, height: 135, backgroundColor: C.paper, boxShadow: `20px 12px 26px ${C.paper}`, opacity: headingOpacity }}>
            <div style={{ fontFamily: sans, fontSize: 24, fontWeight: 500, lineHeight: 1.2, color: C.slate }}>They still obey physics.</div>
            <div style={{ marginTop: 13, fontFamily: "'Manrope', Arial, sans-serif", fontWeight: 600, fontSize: 51, lineHeight: 1.15, letterSpacing: -1.6, color: C.ink, whiteSpace: "nowrap" }}>Human beings aren't built for that.</div>
