  { key: "strong", x: 980, y: 270, cue: 243, fallback: 342, qualifier: "enough to stop bullets,", spans: [{ word: "enough", id: 244, f: 365 }, { word: "to", id: 245, f: 389 }, { word: "stop", id: 246, f: 412 }, { word: "bullets,", id: 247, f: 435 }] },
  { key: "flexible", x: 180, y: 635, cue: 248, fallback: 458, qualifier: "enough to move,", spans: [{ word: "enough", id: 249, f: 481 }, { word: "to", id: 250, f: 505 }, { word: "move,", id: 251, f: 528 }] },
  { key: "small", x: 980, y: 635, cue: 253, fallback: 574, qualifier: "enough to fit around a human body.", spans: [{ word: "enough", id: 254, f: 597 }, { word: "to", id: 255, f: 621 }, { word: "fit", id: 256, f: 644 }, { word: "around", id: 257, f: 667 }, { word: "a", id: 258, f: 690 }, { word: "human", id: 259, f: 713 }, { word: "body.", id: 260, f: 737 }] }
];

type Cue = { wordIndex?: number; index?: number; id?: number | string; startFrame?: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: Cue[] };

const arc = (cx: number, cy: number, r: number, a: number, b: number) => {
  const point = (deg: number) => ({ x: cx + Math.cos(deg * Math.PI / 180) * r, y: cy + Math.sin(deg * Math.PI / 180) * r });
  const s = point(a); const e = point(b);
  return `M ${s.x} ${s.y} A ${r} ${r} 0 ${b - a > 180 ? 1 : 0} 1 ${e.x} ${e.y}`;
};

const OpenGauge = ({ cx, cy, named, opacity = 1 }: { cx: number; cy: number; named: number; opacity?: number }) => (
  <g opacity={opacity}>
    <path d={arc(cx, cy, 61, 42, 318)} fill="none" stroke={P.line} strokeWidth={2.2} strokeLinecap="round" />
    <path d={arc(cx, cy, 61, 42, 318)} fill="none" stroke={P.teal} strokeOpacity={named * 0.9} strokeWidth={2.2} strokeLinecap="round" />
    <path d={`M ${cx - 11} ${cy} H ${cx + 11} M ${cx} ${cy - 11} V ${cy + 11}`} stroke={P.slate} strokeOpacity={0.35} strokeWidth={1.25} fill="none" />
    <path d={`M ${cx - 74} ${cy + 80} V ${cy + 88} H ${cx + 74} V ${cy + 80}`} fill="none" stroke={P.line} strokeWidth={1.2} />
    <path d={`M ${cx + 85} ${cy - 70} H ${cx + 94} V ${cy + 69} H ${cx + 85}`} fill="none" stroke={P.line} strokeWidth={1.2} />
  </g>
);

const Reticle = ({ x, y, opacity, rotation = 0 }: { x: number; y: number; opacity: number; rotation?: number }) => (
  <g transform={`translate(${x} ${y})`} opacity={opacity}>
    <g transform={`rotate(${rotation})`} fill="none" stroke={P.coral} strokeWidth={2.5} strokeLinecap="round">
      <path d={arc(0, 0, 79, 9, 84)} /><path d={arc(0, 0, 79, 99, 174)} />
      <path d={arc(0, 0, 79, 189, 264)} /><path d={arc(0, 0, 79, 279, 354)} />
    </g>
    <path d="M -95 0 H -86 M 86 0 H 95 M 0 -95 V -86 M 0 86 V 95" fill="none" stroke={P.coral} strokeWidth={1.5} />
  </g>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1, 821);
  const cueFrame = (id: number, fallback: number) => {
    const match = cues.find((c) => c.wordIndex === id || c.index === id || c.id === id || c.id === `W${id}`);
    if (match && typeof match.startFrame === "number") return match.startFrame;
    if (cues.length === 33 && cues[id - 228] && typeof cues[id - 228].startFrame === "number") return cues[id - 228].startFrame as number;
    return fallback;
  };
  const at = (start: number, length = 18) => interpolate(f, [start, start + length], [0, 1], { ...CLAMP, easing: EASE });
  const entrance = spring({ frame: f - 3, fps, config: { stiffness: 160, damping: 14, mass: 1 }, durationInFrames: 60 });
  const opening = at(3, 77);
  const boardOpacity = at(3, 20);
  const simStart = cueFrame(237, 203);
  const lightStart = cueFrame(238, 226);
  const strongStart = cueFrame(243, 342);
  const flexibleStart = cueFrame(248, 458);
  const smallStart = cueFrame(253, 574);
  const humanStart = cueFrame(259, 713);
  const bodyStart = cueFrame(260, 737);
  const settleFrame = Math.min(760, bodyStart + 23);
  const bracket = interpolate(f, [simStart, Math.max(simStart + 1, lightStart)], [0, 1], { ...CLAMP, easing: Easing.inOut(Easing.cubic) });
  const focusFade = 1 - interpolate(f, [humanStart, Math.max(humanStart + 1, settleFrame)], [0, 1], { ...CLAMP, easing: EASE });

  const gaugeCenters = SLABS.map((s) => ({ x: s.x + 631, y: s.y + 128 }));
  let inspectX = gaugeCenters[0].x;
  let inspectY = gaugeCenters[0].y;
  let inspectIndex = 0;
  let travel = 1;
  [strongStart, flexibleStart, smallStart].forEach((start, index) => {
    if (f >= start) {
      const t = interpolate(f, [start, start + 25], [0, 1], { ...CLAMP, easing: EASE });
      inspectX = interpolate(t, [0, 1], [gaugeCenters[index].x, gaugeCenters[index + 1].x]);
      inspectY = interpolate(t, [0, 1], [gaugeCenters[index].y, gaugeCenters[index + 1].y]);
      inspectIndex = index + 1;
      travel = t;
    }
  });

  const cameraKeys = [
    { t: 3, z: 2.65, x: gaugeCenters[0].x, y: gaugeCenters[0].y },
    { t: 80, z: 1, x: 960, y: 540 },
    { t: lightStart, z: 1, x: 960, y: 540 },
    { t: lightStart + 25, z: 1.12, x: 830, y: 505 },
    { t: strongStart, z: 1.12, x: 830, y: 505 },
    { t: strongStart + 25, z: 1.12, x: 1090, y: 505 },
    { t: flexibleStart, z: 1.12, x: 1090, y: 505 },
    { t: flexibleStart + 25, z: 1.12, x: 830, y: 645 },
    { t: smallStart, z: 1.12, x: 830, y: 645 },
    { t: smallStart + 25, z: 1.12, x: 1090, y: 645 },
    { t: humanStart, z: 1.12, x: 1090, y: 645 },
    { t: settleFrame, z: 1, x: 960, y: 540 }
  ];
  let camera = cameraKeys[0];
  for (let i = 0; i < cameraKeys.length - 1; i++) {
    const a = cameraKeys[i]; const b = cameraKeys[i + 1];
    if (f >= a.t) {
      const u = interpolate(f, [a.t, Math.max(a.t + 1, b.t)], [0, 1], { ...CLAMP, easing: EASE });
      camera = { t: f, z: a.z + (b.z - a.z) * u, x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u };
    }
  }
  const zoom = camera.z;
  const panX = 960 - camera.x * zoom;
  const panY = 540 - camera.y * zoom;
  const stageDy = f < 80 ? (1 - entrance) * 20 * opening : 0;
  const brassBoundary = 1 - at(3, 28);
  const reticleOpacity = at(lightStart, 14) * focusFade;
