  return (
    <AbsoluteFill style={{ backgroundColor: P.paper, overflow: "hidden", color: P.ink, fontFamily: FONT.sans }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * pageScale) / 2, top: (height - 1080 * pageScale) / 2, transform: `scale(${pageScale})`, transformOrigin: "0 0", overflow: "hidden", backgroundColor: P.paper }}>
        <AbsoluteFill style={{ backgroundColor: P.dark, opacity: 1 - at(3, 13) }} />
        <div style={{ position: "absolute", inset: 0, opacity: boardOpacity * 0.5, backgroundImage: "radial-gradient(circle, rgba(101,117,124,0.2) 0.7px, transparent 0.9px)", backgroundSize: "32px 32px" }} />

        <div style={{ position: "absolute", width: 1920, height: 1080, left: 0, top: 0, transformOrigin: "0 0", transform: `translate(${panX}px, ${panY}px) scale(${zoom})` }}>
          <div style={{ position: "absolute", inset: 0, transform: `translateY(${stageDy}px)` }}>
            <div style={{ position: "absolute", left: STAGE.x, top: STAGE.y, width: STAGE.w, height: STAGE.h, borderRadius: 18, backgroundColor: P.paper, border: "1px solid rgba(101,117,124,0.22)", boxShadow: "0 16px 48px rgba(23,38,44,0.065)", opacity: boardOpacity }} />

            <svg width={1920} height={1080} style={{ position: "absolute", inset: 0, opacity: boardOpacity }}>
              <path d="M 176 232 H 1744 M 960 280 V 956 M 184 617.5 H 1736" stroke={P.line} strokeWidth={1} fill="none" />
              <path d="M 154 154 H 166 M 160 148 V 160 M 1754 154 H 1766 M 1760 148 V 160 M 154 992 H 166 M 160 986 V 998 M 1754 992 H 1766 M 1760 986 V 998" stroke={P.slate} strokeOpacity={0.38} strokeWidth={1} />
            </svg>

            {SLABS.map((s, index) => {
              const start = cueFrame(s.cue, s.fallback);
              const named = at(start, 18);
              const reveal = spring({ frame: f - start, fps, config: { stiffness: 160, damping: 14 }, durationInFrames: 32 });
              const next = index === 0 ? strongStart : index === 1 ? flexibleStart : index === 2 ? smallStart : humanStart;
              const active = at(start, 16) * (1 - at(next, index === 3 ? 47 : 20));
              const slabIn = at(3 + index * 4, 27);
              return (
                <div key={s.key} style={{ position: "absolute", left: s.x, top: s.y, width: 760, height: 330, borderRadius: 10, backgroundColor: P.surface, border: `1px solid ${P.line}`, boxSizing: "border-box", boxShadow: "0 5px 16px rgba(23,38,44,0.035)", opacity: slabIn }}>
                  <svg width={760} height={330} style={{ position: "absolute", inset: 0 }}>
                    <path d="M 31 69 H 24 V 242 H 31 M 45 275 V 282 H 706 V 275" fill="none" stroke={P.line} strokeWidth={1.15} />
                    <path d="M 45 282 H 706" stroke={P.teal} strokeOpacity={named * 0.25} strokeWidth={1.15} />
                    <path d="M 742 14 H 728 M 742 14 V 28 M 18 316 H 32 M 18 316 V 302" stroke={P.line} strokeWidth={1} />
                  </svg>
                  <div style={{ position: "absolute", left: 50, top: 39, opacity: named, transform: `translateY(${(1 - reveal) * 18}px)`, fontFamily: FONT.head, fontSize: s.key === "flexible" ? 91 : 106, fontWeight: 600, lineHeight: 1.2, letterSpacing: -5, color: P.ink }}>{s.key}</div>
                  <div style={{ position: "absolute", left: 52, top: 205, right: 27, display: "flex", flexWrap: "nowrap", gap: 7.5, alignItems: "baseline", whiteSpace: "nowrap", fontFamily: FONT.sans, fontWeight: 400, fontSize: 29, lineHeight: "38px", letterSpacing: -0.4 }}>
                    {s.spans.map((part) => {
                      const wordReveal = at(cueFrame(part.id, part.f), 10);
                      return <span key={part.id} style={{ display: "inline-block", opacity: wordReveal, transform: `translateY(${(1 - wordReveal) * 6}px)`, color: P.slate }}>{part.word}</span>;
                    })}
                  </div>
                  <div style={{ position: "absolute", left: 50, top: 38, width: 34, height: 3, borderRadius: 2, backgroundColor: P.teal, opacity: named * 0.65 }} />
                  <div style={{ position: "absolute", left: -1, top: -1, width: 760, height: 330, borderRadius: 10, boxSizing: "border-box", border: "1px solid rgba(233,107,83,0.35)", opacity: active * 0.7, pointerEvents: "none" }} />
                </div>
              );
            })}

            <svg width={1920} height={1080} style={{ position: "absolute", inset: 0, overflow: "visible", pointerEvents: "none" }}>
              {SLABS.map((s, i) => <OpenGauge key={s.key} cx={gaugeCenters[i].x} cy={gaugeCenters[i].y} named={at(cueFrame(s.cue, s.fallback), 24)} opacity={i === 0 ? 1 : at(3 + i * 4, 27)} />)}
              <g opacity={brassBoundary}>
                <circle cx={gaugeCenters[0].x} cy={gaugeCenters[0].y} r={61} fill="none" stroke={P.brass} strokeWidth={2.2} />
                <path d={arc(gaugeCenters[0].x, gaugeCenters[0].y, 69, 196, 269)} fill="none" stroke={P.brass} strokeOpacity={0.35} strokeWidth={0.8} />
              </g>
              <path d="M 162 290 V 269 Q 162 252 180 252 H 1740 Q 1758 252 1758 270 V 964 Q 1758 982 1740 982 H 180 Q 162 982 162 964 V 290" pathLength={1} stroke={P.coral} strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" fill="none" strokeDasharray="1 1" strokeDashoffset={1 - bracket} opacity={f < simStart ? 0 : 0.88} />
              <Reticle x={inspectX} y={inspectY} opacity={reticleOpacity} rotation={inspectIndex * 15 + travel * 12} />
            </svg>

            <div style={{ position: "absolute", left: currentSlab.x + 17, top: currentSlab.y + 17, width: 726, height: 296, opacity: slabFocus * 0.38, pointerEvents: "none" }}>
              <FocusFrame color={P.coral} frameAt={lightStart} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", color: P.coral, borderRadius: 5 }} />
              <svg width={726} height={296} style={{ position: "absolute", inset: 0 }}><path d="M 0 19 V 0 H 19 M 707 0 H 726 V 19 M 726 277 V 296 H 707 M 19 296 H 0 V 277" fill="none" stroke={P.coral} strokeWidth={1.5} /></svg>
            </div>

            <div style={{ position: "absolute", left: 180, top: 992, width: 1560, height: 12, boxSizing: "border-box", borderTop: "1px solid #C6CECB", borderBottom: "1px solid #C6CECB", backgroundColor: "#DEE3DF", opacity: bandOpacity }}>
              <div style={{ position: "absolute", left: 780, top: 0, bottom: 0, width: 1, backgroundColor: "#BFC9C5" }} />
              <div style={{ position: "absolute", left: 0, top: -4, height: 20, width: 1, backgroundColor: "#BFC9C5" }} />
              <div style={{ position: "absolute", right: 0, top: -4, height: 20, width: 1, backgroundColor: "#BFC9C5" }} />
            </div>
          </div>
        </div>

        <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 220, background: "linear-gradient(180deg, #F3F1EB 0%, #F3F1EB 75%, rgba(243,241,235,0) 100%)", opacity: at(3, 24), pointerEvents: "none" }} />
        <div style={{ position: "absolute", left: 100, top: 67, width: 1080, height: 150, opacity: boardOpacity, transform: `translateY(${(1 - entrance) * 12}px)` }}>
          <div style={{ position: "absolute", left: 0, top: 0, display: "flex", alignItems: "center", gap: 13, opacity: at(simStart, 16), color: P.coral }}>
            <span style={{ display: "block", width: 27, height: 2, backgroundColor: P.coral, transform: `scaleX(${bracket})`, transformOrigin: "left center" }} />
            <span style={{ fontFamily: FONT.sans, fontWeight: 500, fontSize: 24, lineHeight: "30px", letterSpacing: 0.8 }}>simultaneously</span>
          </div>
          <Heading kicker="" title="Then comes the armor." frameAt={3} style={{ position: "absolute", left: 0, top: 40, maxWidth: 1080, fontFamily: FONT.head, fontSize: 54, fontWeight: 600, lineHeight: 1.15, letterSpacing: -1.8, color: P.ink, whiteSpace: "nowrap" }} />
        </div>
        <div style={{ position: "absolute", right: 176, top: 189, fontFamily: FONT.mono, fontSize: 26, fontWeight: 400, lineHeight: "32px", letterSpacing: 0.6, color: P.slate, opacity: at(42, 30), fontVariantNumeric: "tabular-nums" }}>SCHEMATIC — NOT MEASURED</div>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
