type WordCue = { index?: number; wordIndex?: number; word?: string; text?: string; startFrame: number; endFrame?: number };
type ShotProps = { wordCues?: WordCue[] };

const C = { paper: '#F3F1EB', white: '#FFFFFF', ink: '#17262C', slate: '#65757C', teal: '#147D87', coral: '#E96B53' };
