export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (index: number) => {
    const original = fallback[index - 261];
    const explicit = cues.find((c) => c.wordIndex === index || c.index === index);
    const positional = cues.length === fallback.length ? cues[index - 261] : undefined;
    const candidate = explicit || positional;
    return { startFrame: candidate?.startFrame ?? original.startFrame, endFrame: candidate?.endFrame ?? original.endFrame };
  };
  const at = (index: number) => cue(index).startFrame;
  const end = (index: number) => cue(index).endFrame;
  const tween = (a: number, b: number) => interpolate(frame, [a, Math.max(a + 1, b)], [0, 1], { ...clamp, easing: ease });
  const reveal = (start: number, length = 12) => tween(start, start + length);
  const enterSpring = (start: number) => frame < start ? 0 : spring({ frame: frame - start, fps, config: { stiffness: 160, damping: 14, mass: 0.65 } });

  const medium = tween(at(265), end(265));
  const travelLeft = tween(at(266), end(268));
  const massFollow = tween(at(269), end(272));
  const travelRight = tween(at(273), end(274));
  const pullback = tween(at(276), end(279));

  let zoom = mix(1.7, 1.18, medium);
  let focusX = 960;
  let focusY = mix(584, 600, medium);
  focusX = mix(focusX, 540, travelLeft);
  focusY = mix(focusY, 644, travelLeft);
  zoom = mix(zoom, 1.48, travelLeft);
  focusX += 32 * massFollow;
  focusY += 78 * massFollow;
  focusX = mix(focusX, 1380, travelRight);
  focusY = mix(focusY, 684, travelRight);
  zoom = mix(zoom, 1.43, travelRight);
  focusX = mix(focusX, 960, pullback);
  focusY = mix(focusY, 540, pullback);
  zoom = mix(zoom, 1, pullback);
  const panX = (960 - focusX) * zoom;
  const panY = (540 - focusY) * zoom;

  const bandSpring = enterSpring(3);
  const seedFade = 1 - tween(at(265), end(265) - 2);
  const branch = tween(at(265), end(265));
  const boardReveal = reveal(at(265), 22);
  const leftIn = Math.min(1, enterSpring(at(266)));
  const rightIn = Math.min(1, enterSpring(at(273)));
  const leftOpacity = reveal(at(266), 12);
  const rightOpacity = reveal(at(273), 12);
  const thick = tween(at(268), end(268));
  const heavy = tween(at(269), end(272));
  const thin = tween(at(275), end(275));
  const loss = tween(at(278), end(279));
  const leftDepth = mix(138, 224, thick);
  const rightDepth = mix(138, 69, thin);
  const massLength = mix(176, 480, heavy);
  const protectionLength = mix(480, 178, loss);
  const leftRailOpacity = reveal(at(269), 10);
  const rightRailOpacity = reveal(at(275), 10);
  const leftStatusOpacity = reveal(at(272), 13);
  const rightStatusOpacity = reveal(at(278), 14);
  const focusToMass = tween(at(269), end(272));
  const focusToProtection = tween(at(278), end(278));
  const focusToPair = tween(at(279), end(279));

  let box = { x: 243, y: 494, w: 594, h: 284 };
  box = {
    x: mix(box.x, 233, focusToMass),
    y: mix(box.y, 787, focusToMass),
    w: mix(box.w, 614, focusToMass),
    h: mix(box.h, 100, focusToMass)
  };
  box = {
    x: mix(box.x, 1083, travelRight),
    y: mix(box.y, 494, travelRight),
    w: mix(box.w, 594, travelRight),
    h: mix(box.h, 284, travelRight)
  };
  box = {
    x: mix(box.x, 1073, focusToProtection),
    y: mix(box.y, 787, focusToProtection),
    w: mix(box.w, 614, focusToProtection),
    h: mix(box.h, 100, focusToProtection)
  };
  box = {
    x: mix(box.x, 178, focusToPair),
    y: mix(box.y, 252, focusToPair),
    w: mix(box.w, 1564, focusToPair),
