const CLAMP = { extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const };
const WORDS = [
  { id: 280, start: 0, text: 'And' }, { id: 281, start: 22, text: 'if' },
  { id: 282, start: 48, text: 'the' }, { id: 283, start: 73, text: 'suit' },
