];

const normalize = (value: string) => value.toLowerCase().replace(/[^a-z0-9]/g, '');
const ramp = (frame: number, start: number, length = 14) => interpolate(frame, [start, start + length], [0, 1], CLAMP);
const ease = (value: number) => Easing.inOut(Easing.cubic)(Math.max(0, Math.min(1, value)));
const keyed = (frame: number, keys: Array<[number, number]>) => {
  if (frame <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i++) {
    if (frame <= keys[i][0]) {
      const t = interpolate(frame, [keys[i - 1][0], keys[i][0]], [0, 1], CLAMP);
      return keys[i - 1][1] + (keys[i][1] - keys[i - 1][1]) * ease(t);
    }
  }
  return keys[keys.length - 1][1];
};

