export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const at = (id: number) => {
    const fallback = WORDS.find((word) => word.id === id)!;
    const indexed = cues.find((cue) => cue.wordIndex === id || cue.index === id);
    const positional = cues.length === WORDS.length ? cues[id - 280] : undefined;
    const matched = cues.find((cue) => normalize(cue.word || cue.text || '') === normalize(fallback.text) && Math.abs((cue.startFrame ?? fallback.start) - fallback.start) < 75);
    const candidate = indexed || positional || matched;
    const start = candidate?.startFrame;
    return typeof start === 'number' && start >= 0 && start < durationInFrames ? start : fallback.start;
  };

  const now = at(286);
  const metal = at(293);
  const electronics = at(294);
  const batteries = at(295);
  const propulsion = at(297);
  const equipment = at(298);
  const attached = at(299);
  const body = at(302);
  const not = at(303);
  const ideal = at(305);
  const finish = Math.min(588, body + 25);
  const handoff = Math.max(713, durationInFrames - 10);
  const queryOpacity = 1 - ramp(frame, now, 48);
  const inventoryOpacity = ramp(frame, now + 7, 42);
  const bracketProgress = ramp(frame, at(289), Math.max(1, at(291) - at(289)));
  const wordReveal = (id: number) => ramp(frame, at(id), 8);
  const reach = ramp(frame, attached, Math.max(1, body - attached));
  const selected = frame < metal ? -1 : frame < electronics ? 0 : frame < batteries ? 1 : frame < propulsion ? 2 : 3;
  const focused = frame >= metal && frame < finish;
  const settle = spring({ frame: Math.max(0, frame - not), fps, config: { stiffness: 78, damping: 17, mass: 1.4 } });
  const burden = frame >= not ? 9 * settle : 0;

  const zoom = keyed(frame, [
    [0, 1.72], [now, 1.72], [at(291), 1], [metal, 1], [metal + 14, 1.10],
