const range = (f: number, times: number[], values: number[]) => interpolate(f, times, values, { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
const curvePath = (q: Curve) => `M ${q.a.x} ${q.a.y} C ${q.b.x} ${q.b.y} ${q.c.x} ${q.c.y} ${q.d.x} ${q.d.y}`;
const pointAt = (q: Curve, t: number): Point => {
  const s = 1 - t;
  return { x: s * s * s * q.a.x + 3 * s * s * t * q.b.x + 3 * s * t * t * q.c.x + t * t * t * q.d.x, y: s * s * s * q.a.y + 3 * s * s * t * q.b.y + 3 * s * t * t * q.c.y + t * t * t * q.d.y };
};
const pathSlice = (q: Curve, t: number, delta: number) => {
  const a = pointAt(q, clamp01(t - delta));
  const b = pointAt(q, clamp01(t));
  const c = pointAt(q, clamp01(t + delta));
  return `M ${a.x} ${a.y} Q ${b.x} ${b.y} ${c.x} ${c.y}`;
};
const flightPoint = (u: number): Point => u < 0.61 ? { x: 1520 - 330 * (u / 0.61), y: 925 } : pointAt({ a: { x: 1190, y: 925 }, b: { x: 1080, y: 925 }, c: { x: 1020, y: 649 }, d: { x: 972, y: 591 } }, (u - 0.61) / 0.39);

