type WordCue = { index?: number; wordIndex?: number; globalIndex?: number; startFrame?: number; text?: string; word?: string };
type ShotProps = { wordCues?: WordCue[] };
const C = { paper: '#F3F1EB', white: '#FFFFFF', ink: '#17262C', slate: '#65757C', teal: '#147D87', coral: '#E96B53', line: '#DCE2DF' };
const SANS = 'IBM Plex Sans, Arial, sans-serif';
const MONO = 'IBM Plex Mono, monospace';
const HEAD = 'Manrope, Arial, sans-serif';
const clamp = (v: number, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const smooth = (v: number) => { const t = clamp(v); return t * t * (3 - 2 * t); };
const ramp = (frame: number, start: number, end: number, a = 0, b = 1) => interpolate(frame, [start, Math.max(start + 1, end)], [a, b], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
const draw = (progress: number, length = 1800) => ({ strokeDasharray: length + ' ' + length, strokeDashoffset: length * (1 - clamp(progress)) });
const linePath = (points: { x: number; y: number }[]) => points.map((p, i) => (i === 0 ? 'M ' : 'L ') + p.x.toFixed(2) + ' ' + p.y.toFixed(2)).join(' ');
const orbitPoint = (t: number) => {
  const points = [{ x: 1588, y: 850 }, { x: 1632, y: 876 }, { x: 1632, y: 901 }, { x: 648, y: 901 }, { x: 620, y: 874 }, { x: 620, y: 620 }, { x: 676, y: 596 }];
  const breaks = [0, 0.05, 0.08, 0.75, 0.78, 0.96, 1];
  const k = Math.max(0, Math.min(points.length - 2, breaks.findIndex((v, i) => i > 0 && t <= v) - 1));
  const u = clamp((t - breaks[k]) / (breaks[k + 1] - breaks[k]));
  return { x: mix(points[k].x, points[k + 1].x, u), y: mix(points[k].y, points[k + 1].y, u) };
};
const forwardPoint = (t: number) => {
  const points = [{ x: 1420, y: 552 }, { x: 1514, y: 552 }, { x: 1550, y: 580 }, { x: 1550, y: 722 }, { x: 1494, y: 754 }];
  const breaks = [0, 0.29, 0.42, 0.83, 1];
  const k = Math.max(0, Math.min(points.length - 2, breaks.findIndex((v, i) => i > 0 && t <= v) - 1));
  const u = clamp((t - breaks[k]) / (breaks[k + 1] - breaks[k]));
  return { x: mix(points[k].x, points[k + 1].x, u), y: mix(points[k].y, points[k + 1].y, u) };
};

