import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

const C = {
  paper: "#F3F1EB",
  surface: "#FFFFFF",
  ink: "#17262C",
  slate: "#65757C",
  teal: "#147D87",
  coral: "#E96B53",
};

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const CAMERA_EASE = Easing.bezier(0.32, 0, 0.18, 1);
const FONT = '"IBM Plex Sans", Arial, sans-serif';
const MONO = '"IBM Plex Mono", monospace';
const STAGE = { left: 120, top: 164, width: 1680, height: 860 };
const DEFAULT_WAYPOINT = { x: 638, y: 596, diameter: 520 };

type WordCue = {
  wordIndex?: number;
  index?: number;
  word?: string;
  text?: string;
  startFrame: number;
  endFrame?: number;
};

type ShotProps = {
  wordCues?: WordCue[];
  inheritedWaypoint?: { x: number; y: number; diameter: number };
};

type Capability = {
  label: string;
  lines: string[];
  x: number;
  y: number;
  cueIndex: number;
  cueWord: string;
  defaultStart: number;
  nounIndex: number;
  nounWord: string;
  defaultEnd: number;
  cameraLead: number;
  cameraWord: string;
  defaultLead: number;
  arrivalOffset: number;
};

const CAPABILITIES: Capability[] = [
  { label: "powered exoskeletons", lines: ["powered", "exoskeletons"], x: 270, y: 330, cueIndex: 375, cueWord: "powered", defaultStart: 303, nounIndex: 376, nounWord: "exoskeletons", defaultEnd: 360, cameraLead: 372, cameraWord: "We", defaultLead: 214, arrivalOffset: 26 },
  { label: "robotic arms", lines: ["robotic", "arms"], x: 610, y: 420, cueIndex: 379, cueWord: "robotic", defaultStart: 417, nounIndex: 380, nounWord: "arms", defaultEnd: 459, cameraLead: 377, cameraWord: "We", defaultLead: 375, arrivalOffset: 13 },
  { label: "autonomous drones", lines: ["autonomous", "drones"], x: 940, y: 300, cueIndex: 383, cueWord: "autonomous", defaultStart: 518, nounIndex: 384, nounWord: "drones", defaultEnd: 570, cameraLead: 381, cameraWord: "We", defaultLead: 466, arrivalOffset: 13 },
  { label: "advanced helmets", lines: ["advanced", "helmets"], x: 1290, y: 370, cueIndex: 387, cueWord: "advanced", defaultStart: 636, nounIndex: 388, nounWord: "helmets", defaultEnd: 692, cameraLead: 385, cameraWord: "We", defaultLead: 579, arrivalOffset: 13 },
  { label: "augmented reality displays", lines: ["augmented", "reality", "displays"], x: 1080, y: 670, cueIndex: 390, cueWord: "augmented", defaultStart: 722, nounIndex: 392, nounWord: "displays", defaultEnd: 806, cameraLead: 389, cameraWord: "and", defaultLead: 694, arrivalOffset: 22 },
];

type Pose = { zoom: number; tx: number; ty: number };
type CameraKey = Pose & { at: number };

const focusPose = (x: number, y: number, zoom: number, sx: number, sy: number): Pose => ({
  zoom,
  tx: sx - (STAGE.left + x) * zoom,
  ty: sy - (STAGE.top + y) * zoom,
});

const mixPose = (a: Pose, b: Pose, progress: number): Pose => ({
  zoom: a.zoom + (b.zoom - a.zoom) * progress,
  tx: a.tx + (b.tx - a.tx) * progress,
  ty: a.ty + (b.ty - a.ty) * progress,
});

const cameraAt = (frame: number, keys: CameraKey[]): Pose => {
  if (frame <= keys[0].at) return keys[0];
  for (let i = 1; i < keys.length; i++) {
    if (frame <= keys[i].at) {
      const a = keys[i - 1];
      const b = keys[i];
      const progress = interpolate(frame, [a.at, Math.max(a.at + 1, b.at)], [0, 1], { ...CLAMP, easing: CAMERA_EASE });
      return mixPose(a, b, progress);
    }
  }
  return keys[keys.length - 1];
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];

  const normalize = (value: string) => value.toLowerCase().replace(/[^a-z]/g, "");
  const findCue = (index: number, word: string, fallback: number) => {
    const indexed = cues.find((cue) => cue.wordIndex === index || cue.index === index);
    if (indexed) return indexed;
    const matches = cues.filter((cue) => normalize(cue.word || cue.text || "") === normalize(word));
    if (matches.length) return matches.reduce((best, cue) => Math.abs(cue.startFrame - fallback) < Math.abs(best.startFrame - fallback) ? cue : best);
    if (cues.length === 28) return cues[index - 365];
    return undefined;
  };
  const start = (index: number, word: string, fallback: number) => findCue(index, word, fallback)?.startFrame ?? fallback;
  const end = (index: number, word: string, fallback: number, defaultStart: number) => {
    const cue = findCue(index, word, defaultStart);
    return cue?.endFrame ?? (cue ? cue.startFrame + fallback - defaultStart : fallback);
  };

  const nounStarts = [332, 438, 544, 665, 779];
  const items = CAPABILITIES.map((item, i) => {
    const reveal = start(item.cueIndex, item.cueWord, item.defaultStart);
    const nounEnd = end(item.nounIndex, item.nounWord, item.defaultEnd, nounStarts[i]);
    return {
      ...item,
      reveal,
      nounEnd,
      lead: start(item.cameraLead, item.cameraWord, item.defaultLead),
      arrival: Math.min(reveal + item.arrivalOffset, nounEnd - 8),
    };
  });

  const inherited = props.inheritedWaypoint || DEFAULT_WAYPOINT;
  const initialZoom = inherited.diameter / 240;
  const initial = focusPose(270, 330, initialZoom, inherited.x, inherited.y);
  const openingEnd = end(371, "interesting", 195, 168);
  const opening = focusPose(270, 330, 1.68, 662, 595);
  const exoskeleton = focusPose(270, 330, 1.72, 686, 601);
  const arms = focusPose(610, 420, 1.7, 900, 590);
  const drones = focusPose(940, 300, 1.74, 992, 587);
  const helmets = focusPose(1290, 370, 1.7, 1100, 583);
  const displays = focusPose(1080, 670, 1.4, 1068, 723);
  const overview: Pose = { zoom: 1, tx: 0, ty: 0 };
  const pullStart = items[4].reveal;
  const completeAt = Math.min(durationInFrames - 1, items[4].nounEnd, 806);
  const displayArrival = Math.min(items[4].arrival, completeAt - 20);
  const pullMid = Math.min(start(391, "reality", 751) + 16, completeAt - 10);
  const displayDepart = mixPose(helmets, displays, 0.48);

  const keys: CameraKey[] = [
    { at: 0, ...initial },
    { at: 18, ...initial },
    { at: openingEnd, ...opening },
    { at: items[0].lead, ...opening },
    { at: items[0].arrival, ...exoskeleton },
    { at: items[1].lead, ...exoskeleton },
    { at: items[1].arrival, ...arms },
    { at: items[2].lead, ...arms },
    { at: items[2].arrival, ...drones },
    { at: items[3].lead, ...drones },
    { at: items[3].arrival, ...helmets },
    { at: items[4].lead, ...helmets },
    { at: pullStart, ...displayDepart },
    { at: displayArrival, ...displays },
    { at: pullMid, ...mixPose(displays, overview, 0.46) },
    { at: completeAt, ...overview },
  ].sort((a, b) => a.at - b.at);
  const camera = cameraAt(frame, keys);
  const rimSpring = spring({ frame: Math.max(0, frame - 3), fps, config: { stiffness: 160, damping: 14, mass: 0.8 } });
  const scanFrom = start(368, "modern", 82);
  const scanTo = end(371, "interesting", 195, 168);
  const scanProgress = interpolate(frame, [scanFrom, scanTo], [0, 1], { ...CLAMP, easing: Easing.inOut(Easing.cubic) });
  const scanOpacity = interpolate(frame, [scanFrom, scanFrom + 15, scanTo - 16, scanTo], [0, 0.58, 0.58, 0], CLAMP);
  const kickerAt = start(372, "We", 214);
  const kickerOpacity = interpolate(frame, [kickerAt, kickerAt + 16], [0, 1], CLAMP);

  return (
    <AbsoluteFill style={{ backgroundColor: C.paper, color: C.ink, overflow: "hidden", fontFamily: FONT }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080, transform: `scale(${width / 1920}, ${height / 1080})`, transformOrigin: "0 0", overflow: "hidden" }}>
        <div style={{ position: "absolute", inset: 0, background: "radial-gradient(ellipse at 34% 43%, #FFFFFF 0%, #F7F5F0 45%, #F3F1EB 80%)" }} />

        <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080, transformOrigin: "0 0", transform: `translate3d(${camera.tx}px, ${camera.ty}px, 0) scale(${camera.zoom})`, willChange: "transform" }}>
          <div style={{ position: "absolute", left: STAGE.left, top: STAGE.top, width: STAGE.width, height: STAGE.height, borderRadius: 10, background: "#FBFAF6", border: "1px solid rgba(101,117,124,0.14)", boxShadow: "0 14px 40px rgba(23,38,44,0.035)", boxSizing: "border-box" }}>
            <div style={{ position: "absolute", inset: 0, borderRadius: 10, opacity: 0.59, backgroundImage: "radial-gradient(circle, rgba(101,117,124,0.30) 0.8px, transparent 1px)", backgroundSize: "32px 32px", backgroundPosition: "14px 14px" }} />

            {[
              { left: 20, top: 20, sx: 1, sy: 1 },
              { left: 1644, top: 20, sx: -1, sy: 1 },
              { left: 20, top: 824, sx: 1, sy: -1 },
              { left: 1644, top: 824, sx: -1, sy: -1 },
            ].map((corner, i) => (
              <div key={`registration-${i}`} style={{ position: "absolute", left: corner.left, top: corner.top, width: 16, height: 16, borderLeft: "1px solid rgba(101,117,124,0.3)", borderTop: "1px solid rgba(101,117,124,0.3)", transform: `scale(${corner.sx}, ${corner.sy})` }} />
            ))}

            {items.map((item, i) => {
              const shown = frame >= item.reveal;
              if (i !== 0 && !shown) return null;
              const revealSpring = spring({ frame: Math.max(0, frame - item.reveal), fps, config: { stiffness: 160, damping: 14, mass: 0.8 } });
              const revealOpacity = interpolate(frame, [item.reveal, item.reveal + 9], [0, 1], CLAMP);
              const settle = interpolate(frame, [item.reveal, item.reveal + 28], [0, 1], CLAMP);
              const apertureScale = i === 0 ? 1 : 0.94 + revealSpring * 0.06;
              const nextLead = items[i + 1]?.lead;
              const focusIn = interpolate(frame, [item.reveal, item.reveal + 11], [0, 1], CLAMP);
              const focusOut = nextLead === undefined
                ? interpolate(frame, [completeAt - 20, completeAt], [1, 0], CLAMP)
                : interpolate(frame, [nextLead, nextLead + 12], [1, 0], CLAMP);
              const focusOpacity = focusIn * focusOut;
              const evidenceFrame = item.reveal + 22;
              const tickSpring = spring({ frame: Math.max(0, frame - evidenceFrame), fps, config: { stiffness: 160, damping: 14, mass: 0.7 } });
              const tickDraw = interpolate(frame, [evidenceFrame, evidenceFrame + 15], [0, 1], CLAMP);
              const rimColor = shown ? "rgba(20,125,135,0.53)" : "rgba(101,117,124,0.64)";
              const shellOpacity = i === 0 ? 1 : revealOpacity;

              return (
                <div key={item.label} aria-label={item.label} style={{ position: "absolute", left: item.x - 120, top: item.y - 120, width: 240, height: 240, opacity: shellOpacity, transform: `scale(${apertureScale})`, transformOrigin: "120px 120px" }}>
                  <div style={{ position: "absolute", inset: 0, borderRadius: "50%", backgroundColor: C.surface, opacity: i === 0 ? Math.min(1, rimSpring) * 0.97 : 0.98, boxShadow: "0 8px 22px rgba(23,38,44,0.05)" }} />
                  <div style={{ position: "absolute", inset: 7, overflow: "hidden", borderRadius: "50%", opacity: i === 0 ? Math.min(1, rimSpring) : 1 }}>
                    <div style={{ position: "absolute", inset: 0, background: "radial-gradient(ellipse at 40% 28%, #FFFFFF 25%, #F6F9F7 100%)" }} />
                    {i === 0 && frame >= scanFrom && frame <= scanTo && (
                      <div style={{ position: "absolute", left: -10, right: -10, top: -48 + scanProgress * 330, height: 52, opacity: scanOpacity, background: "linear-gradient(to bottom, rgba(20,125,135,0), rgba(20,125,135,0.08))", borderBottom: "1px solid rgba(20,125,135,0.52)" }} />
                    )}
