                    <path d="M 120 -7 V 3 M 237 120 H 247 M 120 237 V 247 M -7 120 H 3" fill="none" stroke={C.slate} strokeOpacity={0.4} strokeWidth={1} opacity={i === 0 ? Math.min(1, rimSpring) : 1} />
                    <path d="M 27 -10 H 5 Q -10 -10 -10 5 V 27 M 213 -10 H 235 Q 250 -10 250 5 V 27 M -10 213 V 235 Q -10 250 5 250 H 27 M 250 213 V 235 Q 250 250 235 250 H 213" fill="none" stroke={C.coral} strokeWidth={2.4} strokeLinecap="square" opacity={focusOpacity * 0.87} />
                  </svg>

                  {frame >= evidenceFrame && (
