        <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 166, background: C.paper, boxShadow: "0 14px 25px rgba(243,241,235,0.9)", pointerEvents: "none" }} />
        <div style={{ position: "absolute", left: 100, top: 33, display: "flex", alignItems: "center", gap: 11, opacity: kickerOpacity, transform: `translateY(${(1 - kickerOpacity) * 5}px)`, fontFamily: FONT, fontSize: 24, fontWeight: 500, lineHeight: "30px", color: C.slate }}>
