        <div style={{ position: "absolute", right: 120, top: 72, color: C.slate, fontFamily: MONO, fontSize: 15, lineHeight: "24px", letterSpacing: "1.8px", opacity: interpolate(frame, [4, 22], [0, 0.65], CLAMP), fontVariantNumeric: "tabular-nums" }}>FIELD NOTES / 13</div>
