import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring } from 'remotion';
import { mg } from '@frame60/mg';

type WordCue = {
  wordIndex?: number;
  index?: number;
  startFrame?: number;
  word?: string;
  text?: string;
};

type ShotProps = { wordCues?: WordCue[] };

const C = {
  paper: '#F3F1EB',
  white: '#FFFFFF',
  ink: '#17262C',
  slate: '#65757C',
  teal: '#147D87',
  coral: '#E96B53',
  mesh: '#DDE3DF',
};
const DISPLAY = 'Manrope, Arial, sans-serif';
const SANS = 'IBM Plex Sans, Arial, sans-serif';
const MONO = 'IBM Plex Mono, monospace';
const CLAMP = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
const Heading = mg.Heading as React.ComponentType<any>;
const FocusFrame = mg.FocusFrame as React.ComponentType<any>;
const STAGE = { x: 120, y: 170, w: 1680, h: 880 };
const J = { x: 727, y: 406 };
const BANK_Y = [154, 266, 378, 490, 602, 714];
const COMPONENTS = [
  'powered exoskeletons',
  'robotic arms',
  'autonomous drones',
  'helmet',
  'augmented reality displays',
  'experimental jet suits',
];
const GATE_X = [948, 1115, 1282, 1449, 1616];
const GATE_NAMES = ['small', 'light', 'powerful', 'safe', 'reliable'];

const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const fade = (f: number, start: number, length = 16) => interpolate(f, [start, start + length], [0, 1], CLAMP);
const smooth = (f: number, start: number, end: number) => {
  const t = interpolate(f, [start, end], [0, 1], CLAMP);
  return t * t * (3 - 2 * t);
};
const cubicPoint = (t: number, y: number) => {
  const u = 1 - t;
  return {
    x: u * u * u * 546 + 3 * u * u * t * 605 + 3 * u * t * t * 629 + t * t * t * 684,
    y: u * u * u * y + 3 * u * u * t * y + 3 * u * t * t * J.y + t * t * t * J.y,
  };
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const at = (index: number, fallback: number, word: string) => {
    const clean = (value: string) => value.toLowerCase().replace(/[^a-z]/g, '');
    const cue = cues.find((c) => c.wordIndex === index || c.index === index)
      || cues.find((c) => clean(c.word || c.text || '') === clean(word));
    return typeof cue?.startFrame === 'number' ? cue.startFrame : fallback;
  };
  const experimental = at(396, 68, 'experimental');
  const suits = at(398, 116, 'suits');
  const individual = at(400, 177, 'individual');
  const pieces = at(401, 202, 'pieces');
  const real = at(403, 252, 'real');
  const problem = at(405, 311, 'problem');
  const combining = at(407, 360, 'combining');
  const all = at(408, 384, 'all');
  const them = at(410, 433, 'them');
  const into = at(411, 457, 'into');
  const gateStarts = [
    at(415, 554, 'small'),
    at(416, 578, 'light'),
    at(417, 603, 'powerful'),
    at(418, 627, 'safe'),
    at(420, 675, 'reliable'),
  ];
  const lastFrame = Math.max(1, durationInFrames - 1);
  const f = Math.min(frame, lastFrame);
  const apertureSpring = spring({ frame: Math.max(0, f - 2), fps, config: { stiffness: 160, damping: 14 } });
  const pillTravel = smooth(f, suits, 139);
  const entrance = spring({ frame: Math.max(0, f - 4), fps, config: { stiffness: 160, damping: 14 } });
  const pullback = smooth(f, 8, 139);
  const gateFinal = gateStarts[4];
  const release = Math.max(699, gateFinal + 24);
  const stop = Math.min(Math.max(release + 29, 728), lastFrame - 1);

  const cameraKeys = [
    { f: 0, z: 1.72, x: 710, y: 468 },
    { f: 24, z: 1.72, x: 727, y: 406 },
    { f: 139, z: 1, x: 840, y: 440 },
    { f: problem - 1, z: 1, x: 840, y: 440 },
    { f: problem + 27, z: 1.38, x: 805, y: 412 },
    { f: combining, z: 1.38, x: 805, y: 412 },
    { f: all, z: 1.35, x: 936, y: 412 },
    { f: them, z: 1.27, x: 1120, y: 414 },
    { f: into, z: 1.24, x: 1225, y: 420 },
    { f: gateStarts[0], z: 1.24, x: 1190, y: 430 },
    { f: gateStarts[1], z: 1.21, x: 1210, y: 430 },
    { f: gateStarts[2], z: 1.18, x: 1230, y: 430 },
    { f: gateStarts[3], z: 1.15, x: 1246, y: 430 },
    { f: gateStarts[4], z: 1.12, x: 1254, y: 430 },
    { f: release, z: 1.12, x: 1254, y: 430 },
    { f: stop, z: 1, x: 840, y: 440 },
  ];
  let camera = cameraKeys[0];
  for (let i = 0; i < cameraKeys.length - 1; i++) {
    const a = cameraKeys[i];
    const b = cameraKeys[i + 1];
    if (f >= a.f && f <= b.f) {
      const t = smooth(f, a.f, b.f);
      camera = { f, z: mix(a.z, b.z, t), x: mix(a.x, b.x, t), y: mix(a.y, b.y, t) };
      break;
    }
    if (f > b.f) camera = b;
  }
  const cameraX = STAGE.w / 2 - camera.z * camera.x;
  const cameraY = STAGE.h / 2 - camera.z * camera.y;
  const activeFlow = smooth(f, combining, into);
  const chamberVisibility = mix(0.3, 1, smooth(f, problem, into));
  const safeProgress = fade(f, gateStarts[3], 16);
  const safeMatch = smooth(f, release, stop);
  const scanX = mix(710, J.x, apertureSpring);
  const scanY = mix(468, J.y, apertureSpring);
  const scanRadius = mix(104, 43, apertureSpring);

  const packetNodes: React.ReactNode[] = [];
  for (let row = 0; row < 6; row++) {
    const bankReady = row === 5 ? fade(f, 126, 13) : fade(f, 8 + row * 4, 16);
    const y = BANK_Y[row];
    for (let n = 0; n < 2; n++) {
      const p = ((f + row * 19 + n * 67) % 144) / 144;
      const point = cubicPoint(p, y);
      const envelope = Math.min(1, p * 9, (1 - p) * 9);
      packetNodes.push(
        <g key={'input-' + row + '-' + n} opacity={bankReady * envelope * 0.88}>
          <circle cx={point.x} cy={point.y} r={8} fill={C.teal} opacity={0.08} />
          <circle cx={point.x} cy={point.y} r={3.6} fill={C.teal} />
        </g>
      );
    }
    const start = combining + row * 6;
    if (f >= start) {
      const p = ((f - start) % 130) / 130;
      const x = mix(769, 1618, p);
      const yy = J.y + Math.sin(Math.PI * p / 2) * (row - 2.5) * 33;
      const envelope = Math.min(1, p * 14, (1 - p) * 7);
      packetNodes.push(
        <g key={'chamber-packet-' + row} opacity={envelope * fade(f, start, 8)}>
          <circle cx={x} cy={yy} r={9} fill={C.teal} opacity={0.07} />
          <rect x={x - 7} y={yy - 2.8} width={14} height={5.6} rx={2.8} fill={C.teal} />
        </g>
      );
    }
  }

  return (
    <AbsoluteFill style={{ backgroundColor: C.paper, color: C.ink, overflow: 'hidden' }}>
      <div style={{ position: 'absolute', width: 1920, height: 1080, left: 0, top: 0, transform: 'scale(' + width / 1920 + ',' + height / 1080 + ')', transformOrigin: '0 0', fontFamily: SANS }}>
        <div style={{ position: 'absolute', inset: 0, backgroundImage: 'radial-gradient(ellipse at 78% 38%, rgba(255,255,255,0.72), transparent 62%)' }} />
        <div style={{ position: 'absolute', left: STAGE.x, top: STAGE.y, width: STAGE.w, height: STAGE.h, borderRadius: 30, overflow: 'hidden', backgroundColor: '#F8F7F2', border: '1px solid #DCE2DC', boxShadow: '0 16px 45px rgba(23,38,44,0.045)' }}>
          <div style={{ position: 'absolute', inset: 0, transform: 'translate(' + cameraX + 'px,' + cameraY + 'px) scale(' + camera.z + ')', transformOrigin: '0 0', willChange: 'transform' }}>
            <div style={{ position: 'absolute', left: -2400, top: -1800, width: 6400, height: 4600, backgroundImage: 'radial-gradient(circle, rgba(93,122,122,0.19) 1px, transparent 1.4px), linear-gradient(rgba(130,153,147,0.045) 1px, transparent 1px), linear-gradient(90deg, rgba(130,153,147,0.045) 1px, transparent 1px)', backgroundSize: '24px 24px, 120px 120px, 120px 120px' }} />
            <div style={{ position: 'absolute', left: 80, top: 53, fontFamily: MONO, fontSize: 21, letterSpacing: '0.06em', color: C.slate, opacity: mix(0.25, 1, pullback) }}>schematic</div>
            <div style={{ position: 'absolute', left: 80, top: 796, width: 460, height: 1, backgroundColor: '#D5DFDA', opacity: fade(f, 100, 39) }} />

            <svg width={1680} height={880} viewBox='0 0 1680 880' style={{ position: 'absolute', inset: 0, overflow: 'visible' }}>
              <defs>
                <linearGradient id='shot14-chamber-fill' x1='0' y1='0' x2='1' y2='0'>
                  <stop offset='0%' stopColor={C.white} stopOpacity='0.88' />
                  <stop offset='100%' stopColor={C.white} stopOpacity='0.28' />
                </linearGradient>
                <linearGradient id='shot14-flow-fade' x1='0' y1='0' x2='1' y2='0'>
                  <stop offset='0%' stopColor={C.teal} stopOpacity='0.48' />
                  <stop offset='85%' stopColor={C.teal} stopOpacity='0.15' />
                  <stop offset='100%' stopColor={C.teal} stopOpacity='0' />
                </linearGradient>
              </defs>
              <g opacity={fade(f, 3, 22)} fill='none' strokeLinecap='round'>
                {BANK_Y.map((y, i) => (
                  <path key={'conduit-' + i} d={'M 546 ' + y + ' C 605 ' + y + ', 629 406, 684 406'} stroke={C.teal} strokeWidth={2.1} opacity={i === 5 ? fade(f, 126, 13) * 0.45 : 0.45} />
                ))}
              </g>
              <g opacity={chamberVisibility}>
                <path d='M 1650 237 H 930 Q 853 237 853 314 V 367 M 853 445 V 501 Q 853 578 930 578 H 1650' fill='none' stroke='#A8BBB9' strokeWidth={2.3} strokeLinecap='round' />
                <path d='M 930 240 H 1648 V 575 H 930 Q 857 575 857 501 V 314 Q 857 240 930 240 Z' fill='url(#shot14-chamber-fill)' />
                <path d='M 1630 237 H 1651 M 1630 578 H 1651' stroke={C.slate} strokeWidth={2.3} opacity={0.4} />
              </g>
              <g fill='none' strokeLinecap='round'>
                <path d='M 770 406 H 853' stroke={C.teal} strokeWidth={2.5} opacity={mix(0.25, 0.7, activeFlow)} />
                {BANK_Y.map((_, i) => (
                  <path key={'interior-lane-' + i} d={'M 853 406 C 1000 406, 1220 ' + (J.y + (i - 2.5) * 33) + ', 1640 ' + (J.y + (i - 2.5) * 33)} stroke='url(#shot14-flow-fade)' strokeWidth={1.35} opacity={activeFlow * 0.65} />
                ))}
              </g>
              {packetNodes}
              <g transform={'translate(' + scanX + ',' + scanY + ')'}>
                <circle r={scanRadius + 10} fill='none' stroke={C.teal} strokeWidth={1} opacity={0.17} />
                <circle r={scanRadius} fill={C.white} stroke={C.teal} strokeWidth={2.5} />
                <circle r={scanRadius - 10} fill='none' stroke={C.teal} strokeWidth={1} opacity={0.2} />
                <path d={'M ' + (-scanRadius - 7) + ' 0 h 14 M ' + (scanRadius - 7) + ' 0 h 14 M 0 ' + (-scanRadius - 7) + ' v 14 M 0 ' + (scanRadius - 7) + ' v 14'} stroke={C.teal} strokeWidth={1.8} />
                <circle r={scanRadius - 5} fill='none' stroke={C.teal} strokeWidth={3} strokeDasharray={(scanRadius * 0.72) + ' ' + (scanRadius * 5.57)} transform={'rotate(' + (-48 + Math.min(f, stop) * 0.7) + ')'} opacity={0.66} />
                <path d='M -15 0 H 15 M 8 -7 L 15 0 L 8 7' fill='none' stroke={C.teal} strokeWidth={2} strokeLinecap='round' strokeLinejoin='round' opacity={fade(f, 18, 16)} />
              </g>
            </svg>

            {COMPONENTS.map((label, i) => {
              const sixth = i === 5;
              const rowStart = sixth ? experimental : 4 + i * 4;
              const reveal = fade(f, rowStart, sixth ? 8 : 14);
              const s = spring({ frame: Math.max(0, f - rowStart), fps, config: { stiffness: 160, damping: 14 } });
              const x = sixth ? mix(1110, 80, pillTravel) : 80 - 23 * (1 - s);
              const y = sixth ? mix(752, BANK_Y[5], pillTravel) : BANK_Y[i];
              const evidence = smooth(f, individual, real + 16);
              const confirmation = fade(f, pieces + i * 7, 15);
              return (
                <div key={label} style={{ position: 'absolute', left: x, top: y - 37 + (sixth ? 11 * (1 - Math.min(s, 1)) : 0), width: 466, height: 74, display: 'flex', alignItems: 'center', boxSizing: 'border-box', padding: '0 26px', borderRadius: 37, backgroundColor: C.white, border: '1.5px solid ' + (sixth || confirmation > 0.5 ? '#7AAEB0' : '#C6D9D6'), boxShadow: '0 5px 15px rgba(23,38,44,0.045)', opacity: reveal, transform: 'scale(' + (sixth ? mix(0.975, 1, Math.min(s, 1)) : 1) + ')', transformOrigin: 'right center' }}>
                  <div style={{ fontFamily: SANS, fontSize: i === 4 ? 28 : 30, lineHeight: 1.1, fontWeight: 500, letterSpacing: '-0.45px', whiteSpace: 'nowrap', color: C.ink }}>{label}</div>
                  <div style={{ position: 'absolute', left: 28, right: 28, bottom: 0, height: 2, backgroundColor: C.teal, borderRadius: 2, opacity: 0.32 * evidence * confirmation }} />
                </div>
              );
            })}

            <div style={{ position: 'absolute', left: 869, top: 160, fontFamily: DISPLAY, fontWeight: 600, fontSize: 34, lineHeight: 1.2, letterSpacing: '-0.7px', color: C.ink, opacity: fade(f, combining, 20), transform: 'translateY(' + 10 * (1 - fade(f, combining, 20)) + 'px)' }}>combining all of them</div>

            {GATE_NAMES.map((name, i) => {
              const start = gateStarts[i];
              const progress = fade(f, start, 9);
              const gateSpring = spring({ frame: Math.max(0, f - start), fps, config: { stiffness: 160, damping: 14 } });
              const gateScale = mix(0.76, 1, gateSpring);
              const gateX = GATE_X[i];
              const safe = i === 3;
              const active = f >= start && (i === 4 || f < gateStarts[i + 1]);
              return (
                <div key={name} style={{ position: 'absolute', left: gateX - 51, top: 251, width: 102, height: 309, opacity: progress, transform: 'translateY(' + 14 * (1 - gateSpring) + 'px)', transformOrigin: 'center center' }}>
                  <svg width={102} height={309} viewBox='0 0 102 309' style={{ position: 'absolute', inset: 0, overflow: 'visible', transform: 'scaleY(' + gateScale + ')' }}>
                    <path d='M 28 7 H 9 V 302 H 28 M 74 7 H 93 V 302 H 74' fill='none' stroke={C.coral} strokeWidth={active ? 3.6 : 2.8} strokeLinecap='round' strokeLinejoin='round' />
                    <path d='M 9 28 H 15 M 87 28 H 93 M 9 281 H 15 M 87 281 H 93' stroke={C.coral} strokeWidth={1.4} opacity={0.5} />
                    {safe && (
                      <g>
                        <circle cx={51} cy={155} r={mix(48, 52, safeMatch)} fill={C.white} fillOpacity={0.72} stroke={C.coral} strokeWidth={2.8} />
                        <circle cx={51} cy={155} r={mix(38, 42, safeMatch)} fill='none' stroke={C.coral} strokeWidth={1} opacity={0.45} />
                        <path d='M 51 96 V 110 M 51 200 V 214 M -8 155 H 6 M 96 155 H 110' fill='none' stroke={C.coral} strokeWidth={1.8} />
                      </g>
                    )}
                  </svg>
                  <div style={{ position: 'absolute', top: 358, left: -32, width: 166, textAlign: 'center', color: C.coral, fontFamily: SANS, fontSize: 29, fontWeight: 500, lineHeight: '36px', whiteSpace: 'nowrap' }}>{name}</div>
                  <div style={{ position: 'absolute', left: 50, top: 313, width: 1, height: 30, backgroundColor: C.coral, opacity: 0.48 }} />
                </div>
              );
            })}

            {f >= gateStarts[0] && (
              <div style={{ position: 'absolute', left: 875, top: 222, width: 793, height: 430, pointerEvents: 'none', opacity: 0.33 * fade(f, gateStarts[0], 18) }}>
                <FocusFrame frameAt={gateStarts[0]} color={C.coral} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', color: C.coral }} />
              </div>
            )}
            <div style={{ position: 'absolute', left: 875, top: 700, width: 792, height: 1, backgroundColor: '#CCD8D2', opacity: 0.6 * safeProgress }} />
          </div>
        </div>

        <div style={{ position: 'absolute', left: 0, top: 0, width: 1920, height: 164, backgroundColor: C.paper }} />
        <Heading kicker='The problem is combining all of them' title='The individual pieces are real.' frameAt={2} style={{ position: 'absolute', left: 100, top: 39, maxWidth: 1400, fontFamily: DISPLAY, color: C.ink, opacity: 0 }} />
        <div style={{ position: 'absolute', left: 100, top: 38, maxWidth: 1500, opacity: fade(f, 2, 10), transform: 'translateY(' + 10 * (1 - entrance) + 'px)' }}>
          <div style={{ fontFamily: SANS, color: C.slate, fontSize: 24, fontWeight: 500, lineHeight: '30px', letterSpacing: '0.1px' }}>The problem is combining all of them</div>
          <div style={{ fontFamily: DISPLAY, color: C.ink, fontSize: 52, fontWeight: 600, lineHeight: '68px', letterSpacing: '-1.75px', whiteSpace: 'nowrap' }}>The individual pieces are real.</div>
          <div style={{ height: 3, width: 124 * fade(f, real, 20), backgroundColor: C.teal, borderRadius: 2, marginTop: 5, opacity: interpolate(f, [real, real + 10, problem, problem + 20], [0, 0.85, 0.85, 0.24], CLAMP) }} />
        </div>
      </div>
    </AbsoluteFill>
