type WordCue = {
  wordIndex?: number; globalIndex?: number; index?: number; id?: number | string;
  startFrame?: number; endFrame?: number; word?: string; text?: string;
};
type ShotProps = { wordCues?: WordCue[] };
type CameraKey = { at: number; z: number; x: number; y: number };
type Ribbon = {
  id: string; x: number; y: number; jx: number; jy: number; left: boolean;
  lead: number; words: [string, number, string, number]; path: string;
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1);
  const cueFor = (index: number): WordCue | undefined => {
    const indexed = cues.find((c) => {
      const key = c.wordIndex ?? c.globalIndex ?? c.index ?? c.id;
      return key === index || key === 'W' + index;
    });
    if (indexed) return indexed;
    const local = cues[index - 450];
    if (local && cues.length === 35) return local;
    return cues.find((c) => (c.word ?? c.text ?? '').toLowerCase().replace(/[.,!?]/g, '') === LOCAL[index][2].toLowerCase());
  };
