  const ramp = (start: number, finish: number) => interpolate(f, [start, Math.max(start + 1, finish)], [0, 1], { ...clamp, easing: smooth });
  const settle = (start: number) => f < start ? 0 : spring({ frame: f - start, fps, config: { stiffness: 160, damping: 14, mass: 0.8 } });
