  const returnProgress = smooth(frame, networkAt, limitsAt + 24);
  const shellProgress = fade(frame, networkAt + 8, Math.max(18, limitsAt - networkAt + 6));
  const centralProgress = spring({ frame: frame - allAt, fps, config: { stiffness: 160, damping: 14, mass: 0.9 } });

  let camera: Point = { x: 520, y: 385 };
  let zoom = 1.72;
  if (settledFrame < allAt) {
    const t = smooth(settledFrame, 4, allAt - 1);
    camera = pointMix({ x: 520, y: 385 }, { x: 785, y: 449 }, t);
    zoom = mix(1.72, 1.2, t);
  } else if (settledFrame < withoutAt) {
    const t = smooth(settledFrame, allAt, withoutAt - 1);
    camera = pointMix({ x: 785, y: 449 }, { x: 820, y: 455 }, t);
    zoom = mix(1.2, 1.53, t);
  } else if (settledFrame < limitAt[0]) {
    const t = smooth(settledFrame, withoutAt, limitsAt + 24);
    camera = pointMix({ x: 820, y: 455 }, { x: 840, y: 450 }, t);
    zoom = mix(1.53, 1, t);
  } else if (settledFrame < pullAt) {
    let angle = sweepAngles[0];
    const sweepKeys = [...limitAt, endSweep];
    const angleKeys = [...sweepAngles, 180];
    for (let i = 0; i < sweepKeys.length - 1; i++) {
      if (settledFrame >= sweepKeys[i]) angle = mix(angleKeys[i], angleKeys[i + 1], smooth(settledFrame, sweepKeys[i], sweepKeys[i + 1]));
    }
    const entry = smooth(settledFrame, limitAt[0], limitAt[0] + 12);
    const orbit = polar(840, 450, 28, angle);
    camera = pointMix({ x: 840, y: 450 }, orbit, entry);
    zoom = mix(1, 1.035, entry);
  } else {
    const t = smooth(settledFrame, pullAt, settleAt);
    camera = pointMix({ x: 812, y: 450 }, { x: 820, y: 430 }, t);
    zoom = mix(1.035, 0.99, t);
  }

  let reticle: Point = { x: 490, y: 385 };
  let reticleRadius = 48;
  if (settledFrame < allAt) {
    const t = smooth(settledFrame, 4, allAt - 1);
    reticle = pointMix({ x: 490, y: 385 }, J, t);
    reticleRadius = mix(48, 57, t);
  } else if (settledFrame < withoutAt) {
    reticle = J;
    reticleRadius = mix(57, 50, smooth(settledFrame, allAt, withoutAt - 1));
  } else if (settledFrame < limitAt[0]) {
    const t = smooth(settledFrame, limitsAt + 7, limitAt[0]);
    const a = polar(820, 540, sweepRadii[0], sweepAngles[0]);
    reticle = pointMix(J, a, t);
    reticleRadius = mix(50, 65, t);
  } else if (settledFrame < endSweep) {
    let angle = sweepAngles[0];
    let radius = sweepRadii[0];
    for (let i = 0; i < limitAt.length - 1; i++) {
      if (settledFrame >= limitAt[i]) {
        const t = smooth(settledFrame, limitAt[i] + 7, limitAt[i + 1]);
        angle = mix(sweepAngles[i], sweepAngles[i + 1], t);
        radius = mix(sweepRadii[i], sweepRadii[i + 1], t);
      }
    }
    reticle = polar(820, 540, radius, angle);
    reticleRadius = 65;
  } else {
    const t = smooth(settledFrame, pullAt, settleAt);
    reticle = pointMix(polar(820, 540, sweepRadii[4], sweepAngles[4]), J, t);
    reticleRadius = mix(65, 54, t);
  }
  const reticleCoral = fade(frame, limitAt[0], 10) * (1 - fade(frame, pullAt, 24));
  const registration = polar(J.x, J.y, 64, -45);
  const gapEmphasis = fade(frame, lackAt, 12);
  const junctionPulse = frame >= lackAt && frame < settleAt ? (Math.sin((frame - lackAt) / 22) + 1) * 0.5 : 0.25;
  const worldTransform = `translate(${stage.w / 2}px, ${stage.h / 2}px) scale(${zoom}) translate(${-camera.x}px, ${-camera.y}px)`;
  const titleOpacity = fade(frame, 2, 12);
  const titleRise = mix(12, 0, Math.min(1, opening));
  const footerOpacity = fade(frame, networkAt + 22, 24);
  const packetFrame = Math.min(frame, settleAt);
  const packetOpacity = fade(frame, makeAt, 12);
  const shellOpacity = Math.max(0, Math.min(1, centralProgress));

  const centralPill = (label: string, x: number, y: number, w: number, at: number, teal: boolean) => {
    const labelProgress = spring({ frame: frame - at, fps, config: { stiffness: 160, damping: 14, mass: 0.7 } });
    return <div key={label} style={{ position: 'absolute', left: x - w / 2, top: y - 50, width: w, height: 100, borderRadius: 50, border: `1.5px solid ${teal ? '#91BAB9' : '#B9C6C6'}`, background: C.white, boxShadow: '0 7px 22px rgba(23,38,44,0.045)', opacity: shellOpacity, display: 'flex', alignItems: 'center', justifyContent: 'center', boxSizing: 'border-box', transform: `scale(${mix(0.94, 1, centralProgress)})` }}>
      {teal && <div style={{ position: 'absolute', left: 19, top: 43, width: 12, height: 12, borderRadius: 6, background: C.teal, opacity: fade(frame, at, 10) }} />}
      <span style={{ fontFamily: sans, fontSize: 32, fontWeight: 600, letterSpacing: -0.6, lineHeight: 1, color: teal ? C.teal : C.ink, whiteSpace: 'nowrap', opacity: Math.max(0, Math.min(1, labelProgress)), transform: `translateY(${mix(7, 0, labelProgress)}px)`, paddingLeft: teal ? 8 : 0 }}>{label}</span>
    </div>;
  };

  return <AbsoluteFill style={{ background: C.paper, overflow: 'hidden', color: C.ink }}>
    <div style={{ position: 'absolute', width: 1920, height: 1080, left: (width - 1920 * Math.min(width / 1920, height / 1080)) / 2, top: (height - 1080 * Math.min(width / 1920, height / 1080)) / 2, transform: `scale(${Math.min(width / 1920, height / 1080)})`, transformOrigin: '0 0', background: C.paper }}>
      <div style={{ position: 'absolute', inset: 0, background: 'radial-gradient(ellipse at 52% 52%, rgba(255,255,255,0.78) 0%, rgba(255,255,255,0.2) 47%, rgba(243,241,235,0) 76%)' }} />
      <div style={{ position: 'absolute', left: stage.x, top: stage.y, width: stage.w, height: stage.h, overflow: 'hidden', borderRadius: 3 }}>
        <svg width={1680} height={900} style={{ position: 'absolute', inset: 0 }} aria-hidden="true">
          <path d="M 0 22 L 0 0 L 24 0 M 1656 0 L 1680 0 L 1680 24 M 0 876 L 0 899 L 24 899 M 1656 899 L 1679 899 L 1679 876" fill="none" stroke="#C5CBC6" strokeWidth="1.4" />
        </svg>
