          <div style={{ position: 'absolute', left: -500, top: -400, width: 2680, height: 1700, opacity: 0.54, backgroundImage: 'radial-gradient(circle, #BFC8C3 0.85px, transparent 1px)', backgroundSize: '40px 40px', backgroundPosition: '0px 0px' }} />
          <svg width={1680} height={900} viewBox="0 0 1680 900" style={{ position: 'absolute', inset: 0, overflow: 'visible' }} aria-hidden="true">
            <defs>
              <linearGradient id="shot20-loop-fade" x1="410" y1="210" x2="1190" y2="820" gradientUnits="userSpaceOnUse"><stop offset="0" stopColor="#8CAAA7" /><stop offset="0.6" stopColor="#B7C8C3" /><stop offset="1" stopColor="#A6BCB7" /></linearGradient>
            </defs>
            <g opacity={mix(0.46, 0.76, Math.min(1, opening))}>
              <path d={arc(820, 470, 360, -171, 166)} fill="none" stroke="url(#shot20-loop-fade)" strokeWidth="1.6" />
              {Array.from({ length: 48 }, (_, i) => {
                const a = -171 + i * 337 / 47;
                const p = polar(820, 470, 365, a);
                const q = polar(820, 470, i % 4 === 0 ? 375 : 370, a);
                return <path key={`tick-${i}`} d={`M ${p.x} ${p.y} L ${q.x} ${q.y}`} stroke="#9EB4AE" strokeWidth={i % 4 === 0 ? 1.3 : 0.9} opacity={i % 4 === 0 ? 0.66 : 0.35} />;
              })}
            </g>
            <g opacity={mix(0.92, 0.48, smooth(frame, allAt, withoutAt))}>
              <path d="M 421 333 H 439 V 451 H 421 M 558 333 H 540 V 379" fill="none" stroke="#879D98" strokeWidth="2" strokeLinecap="square" />
              <path d="M 440 385 H 752 Q 771 385 779 401" fill="none" stroke="#8AA9A4" strokeWidth="2" pathLength={1} strokeDasharray="1" strokeDashoffset={1 - Math.min(1, opening * 0.17 + smooth(frame, 5, allAt - 1) * 0.83)} />
              <path d="M 454 324 V 316 M 463 324 V 320 M 472 324 V 316" fill="none" stroke="#ABBAB4" strokeWidth="1" />
            </g>
            <g opacity={returnProgress} fill="none" stroke="#A2B6B2" strokeWidth="2.1" strokeLinecap="round">
              {paths.map((p, i) => <path key={`return-${i}`} d={curvePath(p)} pathLength={1} strokeDasharray="1" strokeDashoffset={1 - returnProgress} />)}
            </g>
            {paths.map((p, i) => {
              const travel = interpolate(frame, [limitAt[i], limitAt[i] + 38], [0, 1], clamp);
              const q = curvePoint(p, travel);
              const visible = frame >= limitAt[i] && frame < limitAt[i] + 38;
              return visible ? <circle key={`trace-${i}`} cx={q.x} cy={q.y} r="4" fill={C.coral} opacity={0.58 * Math.sin(Math.PI * travel)} /> : null;
            })}
            <g opacity={fade(frame, 5, 18)}>
              <path d="M 485 430 H 784 M 856 430 H 1150" fill="none" stroke="#97B4B1" strokeWidth="2.4" strokeLinecap="round" />
              <path d="M 719 424 L 725 430 L 719 436 M 895 424 L 901 430 L 895 436" fill="none" stroke={C.teal} strokeWidth="1.6" opacity={0.48 * fade(frame, makeAt, 12)} />
              {Array.from({ length: 4 }, (_, i) => {
                const t = ((packetFrame - makeAt + i * 23 + 10000) % 92) / 92;
                const x = mix(497, 777, t);
                const o = Math.min(1, t * 8, (1 - t) * 9) * packetOpacity;
                return <g key={`packet-left-${i}`} opacity={Math.max(0, o)}><rect x={x - 7} y="426" width="14" height="8" rx="4" fill={C.teal} /><rect x={x - 15} y="428" width="6" height="4" rx="2" fill={C.teal} opacity="0.24" /></g>;
              })}
              {Array.from({ length: 3 }, (_, i) => {
                const t = ((packetFrame - makeAt + i * 27 + 10000) % 96) / 96;
                const x = mix(865, 1152, t);
                const o = Math.min(1, t * 9, (1 - t) * 8) * packetOpacity * 0.76;
                return <g key={`packet-right-${i}`} opacity={Math.max(0, o)}><rect x={x - 7} y="426" width="14" height="8" rx="4" fill={C.teal} /><rect x={x - 15} y="428" width="6" height="4" rx="2" fill={C.teal} opacity="0.24" /></g>;
              })}
            </g>
            <g opacity={Math.max(0, Math.min(1, opening))} transform={`translate(820 430) scale(${mix(0.78, 1, opening)}) translate(-820 -430)`}>
              <circle cx="820" cy="430" r="31" fill={C.paper} />
              <path d={arc(820, 430, 34, 26, 154)} fill="none" stroke={C.coral} strokeWidth="2.5" strokeLinecap="round" />
              <path d={arc(820, 430, 34, 206, 334)} fill="none" stroke={C.coral} strokeWidth="2.5" strokeLinecap="round" />
              <path d="M 784 421 V 439 M 856 421 V 439" fill="none" stroke={C.coral} strokeWidth="2.4" strokeLinecap="round" opacity={mix(0.35, 1, gapEmphasis)} />
              <path d={arc(820, 430, 42, 210, 330)} fill="none" stroke={C.coral} strokeWidth="1" opacity={(0.10 + junctionPulse * 0.11) * gapEmphasis} />
              <path d={arc(820, 430, 42, 30, 150)} fill="none" stroke={C.coral} strokeWidth="1" opacity={(0.10 + junctionPulse * 0.11) * gapEmphasis} />
              <path d="M 820 395 V 354 M 812 354 H 828" fill="none" stroke={C.coral} strokeWidth="1.2" opacity={fade(frame, wayAt, 14)} />
            </g>
            <g opacity={fade(frame, allAt, 15) * 0.65}>
              <path d={`M ${registration.x - 5} ${registration.y + 5} L ${registration.x + 4} ${registration.y - 4} L ${registration.x + 13} ${registration.y - 4}`} fill="none" stroke={C.slate} strokeWidth="1.3" />
            </g>
            {positions.map((p, i) => <g key={`sonar-${i}`}>
              {[0, 7].map((delay, ring) => {
                const age = frame - limitAt[i] - delay;
                const t = interpolate(age, [0, 29], [0, 1], clamp);
                const visible = age >= 0 && age <= 29;
                return <circle key={ring} cx={p.x} cy={p.y} r={mix(39, 80, t)} fill="none" stroke={C.coral} strokeWidth={ring === 0 ? 1.6 : 1} opacity={visible ? (1 - t) * (ring === 0 ? 0.36 : 0.2) : 0} />;
              })}
            </g>)}
            <g transform={`translate(${reticle.x} ${reticle.y})`} opacity="0.76">
              {[[-172, -111], [-82, -21], [8, 69], [98, 159]].map((a, i) => <path key={`reticle-${i}`} d={arc(0, 0, reticleRadius, a[0], a[1])} fill="none" stroke={reticleCoral > 0.5 ? C.coral : C.teal} strokeWidth="1.2" opacity={reticleCoral > 0.5 ? 0.6 : 0.62} />)}
              {[0, 90, 180, 270].map(a => {
                const p = polar(0, 0, reticleRadius + 3, a);
                const q = polar(0, 0, reticleRadius + 10, a);
                return <path key={`reticle-pin-${a}`} d={`M ${p.x} ${p.y} L ${q.x} ${q.y}`} stroke={C.slate} strokeWidth="1.1" opacity="0.65" />;
              })}
              <path d={arc(0, 0, reticleRadius + 9, -51, -39)} fill="none" stroke={C.teal} strokeWidth="2.1" opacity="0.8" />
            </g>
          </svg>

          <div style={{ position: 'absolute', left: 695, top: 308, width: 250, textAlign: 'center', fontFamily: sans, fontSize: 25, fontWeight: 500, color: C.coral, opacity: fade(frame, wayAt, 14), transform: `translateY(${mix(5, 0, smooth(frame, wayAt, wayAt + 18))}px)` }}><span style={{ background: C.paper, padding: '3px 12px' }}>We lack a way</span></div>
          {centralPill('technologies', 620, 430, 280, technologiesAt, true)}
          <div style={{ position: 'absolute', left: 870, top: 380, width: 280, height: 100, borderRadius: 50, border: '1.5px solid #B9C6C6', background: C.white, boxShadow: '0 7px 22px rgba(23,38,44,0.045)', boxSizing: 'border-box', display: 'flex', alignItems: 'center', justifyContent: 'center', opacity: shellOpacity, transform: `scale(${mix(0.94, 1, centralProgress)})` }}>
            <span style={{ fontFamily: sans, fontSize: 32, fontWeight: 600, letterSpacing: -0.6, lineHeight: 1, whiteSpace: 'nowrap' }}><span style={{ opacity: fade(frame, workAt, 10) }}>work</span><span style={{ opacity: fade(frame, togetherAt, 10) }}> together</span></span>
          </div>
          {positions.map((p, i) => {
            const named = fade(frame, limitAt[i], 10);
            const age = frame - limitAt[i];
            const emphasis = age >= 0 ? interpolate(age, [0, 5, 23, 38], [0, 0.13, 0.04, 0], clamp) : 0;
            return <div key={labels[i]} style={{ position: 'absolute', left: p.x - 120, top: p.y - 38, width: 240, height: 76, borderRadius: 38, boxSizing: 'border-box', border: '1.5px solid #D8BBB1', background: C.white, boxShadow: '0 4px 16px rgba(23,38,44,0.028)', opacity: shellProgress, transform: `translateY(${mix(7, 0, shellProgress)}px)`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <div style={{ position: 'absolute', inset: -1, borderRadius: 38, background: C.coral, opacity: emphasis, pointerEvents: 'none' }} />
              <div style={{ position: 'absolute', left: 19, top: 33, width: 9, height: 9, borderRadius: 5, background: C.coral, opacity: 0.7 }} />
              <span style={{ fontFamily: sans, fontSize: 28, fontWeight: 500, lineHeight: 1, color: C.ink, whiteSpace: 'nowrap', paddingLeft: 10, opacity: named }}>
                {i === 4 ? <><span>human</span><span style={{ opacity: fade(frame, biologyAt, 10) }}> biology</span></> : labels[i]}
              </span>
            </div>;
          })}
        </div>
        <div style={{ position: 'absolute', left: 26, bottom: 26, display: 'flex', alignItems: 'center', gap: 16, opacity: footerOpacity, background: C.paper, padding: '5px 10px 5px 0' }}>
          <div style={{ width: 28, height: 1, background: '#9CAAA4' }} />
          <div style={{ fontFamily: mono, fontSize: 17, fontWeight: 400, letterSpacing: 1.7, color: C.slate }}>SCHEMATIC — NOT MEASURED.</div>
        </div>
      </div>
      <div style={{ position: 'absolute', left: 96, top: 0, width: 1740, height: 150, background: 'linear-gradient(180deg, #F3F1EB 0%, #F3F1EB 87%, rgba(243,241,235,0) 100%)', pointerEvents: 'none' }} />
      <div style={{ position: 'absolute', left: 100, top: 43, opacity: titleOpacity, transform: `translateY(${titleRise}px)` }}>
        <div style={{ display: 'flex', gap: 11, alignItems: 'center', marginBottom: 6 }}><div style={{ width: 6, height: 6, borderRadius: 3, background: C.coral }} /><div style={{ fontFamily: sans, fontSize: 24, fontWeight: 500, lineHeight: 1.2, color: C.slate }}>We lack a way</div></div>
        <div style={{ fontFamily: display, fontSize: 52, fontWeight: 600, lineHeight: 1.13, letterSpacing: -1.8, whiteSpace: 'nowrap', color: C.ink }}>work together</div>
      </div>
    </div>
  </AbsoluteFill>;
};

import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { index?: number; wordIndex?: number; startFrame: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };

const C = {
  paper: '#F3F1EB', surface: '#FFFFFF', ink: '#17262C', slate: '#65757C',
  teal: '#147D87', coral: '#E96B53', brass: '#BA934C', graphite: '#9EA6A4', rule: '#DCDDD5'
};
const clamp = { extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const };
const ease = Easing.bezier(0.42, 0, 0.18, 1);
const BANDS: Array<{ points: string; top: number; right: number }> = [
  { points: '550,0 770,0 807,38 513,38', top: 0, right: 789 },
  { points: '513,40 807,40 831,78 489,78', top: 40, right: 820 },
  { points: '489,80 831,80 850,118 470,118', top: 80, right: 841 },
  { points: '470,120 850,120 842,158 478,158', top: 120, right: 846 },
  { points: '478,160 842,160 831,198 489,198', top: 160, right: 837 },
  { points: '489,200 831,200 816,238 504,238', top: 200, right: 824 },
  { points: '504,240 816,240 800,278 520,278', top: 240, right: 808 },
  { points: '520,280 800,280 784,318 536,318', top: 280, right: 792 },
  { points: '536,320 784,320 762,358 558,358', top: 320, right: 773 },
  { points: '558,360 762,360 718,398 602,398', top: 360, right: 740 }
];

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueFrame = (id: number, fallback: number) => {
    const indexed = cues.find((cue) => cue.wordIndex === id || cue.index === id);
    if (indexed && Number.isFinite(indexed.startFrame)) return indexed.startFrame;
    const positional = cues.length === 20 ? cues[id - 574] : undefined;
    return positional && Number.isFinite(positional.startFrame) ? positional.startFrame : fallback;
  };
  const t = {
    iron: cueFrame(575, 21), man: cueFrame(576, 46), isnt: cueFrame(577, 71),
    really: cueFrame(578, 96), one: cueFrame(579, 121), impossible: cueFrame(580, 146),
    invention: cueFrame(581, 171), hes: cueFrame(582, 213), about: cueFrame(583, 238),
    ten: cueFrame(584, 263), extremely: cueFrame(585, 287), difficult: cueFrame(586, 312),
    inventions: cueFrame(587, 337), stacked: cueFrame(588, 361), on: cueFrame(589, 386),
    top: cueFrame(590, 411), of: cueFrame(591, 436), each: cueFrame(592, 460), other: cueFrame(593, 485)
  };
  const progress = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { ...clamp, easing: ease });
  const endHold = Math.min(durationInFrames - 1, 539);
  const explosionEnd = Math.min(287, t.ten + 24);
  const finalAt = Math.min(509, endHold);
  const entrance = spring({ frame: frame - 2, fps, config: { stiffness: 160, damping: 14, mass: 0.72 } });
  const badgeLift = 28 * (1 - entrance);
  const stagger = progress(t.isnt, t.one + 16);
  const explosion = progress(t.about, explosionEnd);
  const bandOffset = (i: number) => badgeLift + i * (3.5 * stagger * (1 - explosion) + 20 * explosion);
  const maskTop = 208;
  const maskBottom = maskTop + 398 + bandOffset(9);

  const cameraKeys = [0, t.iron, t.man + 24, t.isnt, t.really, t.one, t.impossible, t.invention + 24, t.hes, t.about, t.ten, explosionEnd, t.difficult, t.inventions, t.stacked, t.top, t.each, finalAt];
  const sample = (values: number[]) => interpolate(frame, cameraKeys, values, { ...clamp, easing: ease });
  const zoom = sample([2.72, 2.72, 1.26, 1.26, 1.52, 1.82, 1.82, 1.73, 1.73, 1.68, 1.30, 1.10, 1.08, 1.08, 1.08, 1.045, 1.02, 1]);
  const panX = sample([-656, -656, 0, 0, -166, -338, -338, -290, -290, -255, -65, 0, 0, 0, 0, 0, 0, 0]);
  const panY = sample([424, 424, 19, 19, 80, 111, 111, 95, 95, 80, 10, -8, -30, -55, -82, -42, -15, 0]);
  const transform = 'translate(' + panX + 'px, ' + panY + 'px) scale(' + zoom + ')';
  const identityFocus = 1 - progress(t.isnt, t.one);
  const axisOpacity = progress(t.isnt, t.one + 12);
  const finalReveal = progress(t.stacked, finalAt);
  const countOpacity = progress(t.about, t.about + 18);
  const typographyOpacity = progress(t.extremely, t.extremely + 18);
  const kickerOpacity = progress(t.stacked, t.stacked + 18);
  const labelOpacity = progress(t.other, finalAt);
  const topEdge = maskTop + bandOffset(0);
  const bracketProgress = progress(t.stacked, finalAt);
  const bracketTop = topEdge - 12;
  const bracketBottom = maskBottom + 12;
  const bracketHeight = bracketBottom - bracketTop;
  const bracketLength = bracketHeight + 56;

  const reticleIndex = interpolate(frame,
    [0, t.isnt, t.one, t.about, explosionEnd, t.difficult, t.inventions, t.stacked, t.on, t.top, finalAt],
    [2, 2, 3, 3, 3, 5, 7, 8, 9, 9, 9], { ...clamp, easing: ease });
  const low = Math.min(9, Math.floor(reticleIndex));
  const high = Math.min(9, low + 1);
  const blend = reticleIndex - low;
  const reticleX = BANDS[low].right + (BANDS[high].right - BANDS[low].right) * blend + 8;
  const reticleY = maskTop + BANDS[low].top + 19 + bandOffset(low) + (BANDS[high].top - BANDS[low].top + bandOffset(high) - bandOffset(low)) * blend;
  const reticleRadius = 25 - 4 * finalReveal;
  const reticleOpacity = 1 - 0.38 * finalReveal;
  const headlineY = 9 * (1 - typographyOpacity);
  const mono = 'IBM Plex Mono, monospace';
  const sans = 'IBM Plex Sans, sans-serif';

  return (
