const BASELINE = 866;
const JUNCTION = { x: 960, y: 620 };
const CURVE_PATH = "M 360 748 C 760 728 1160 454 1560 356";

function curvePoint(t: number): Point {
  const u = 1 - t;
  return {
    x: u * u * u * CURVE_START.x + 3 * u * u * t * CURVE_C1.x + 3 * u * t * t * CURVE_C2.x + t * t * t * CURVE_END.x,
    y: u * u * u * CURVE_START.y + 3 * u * u * t * CURVE_C1.y + 3 * u * t * t * CURVE_C2.y + t * t * t * CURVE_END.y
  };
}

function curveSection(a: number, b: number, steps = 72): string {
  return Array.from({ length: steps + 1 }, (_, i) => {
    const p = curvePoint(a + (b - a) * i / steps);
    return (i === 0 ? "M " : "L ") + p.x.toFixed(2) + " " + p.y.toFixed(2);
  }).join(" ");
}

